(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("catullus-poems-b", [{"sp": "HDR", "t": "Carmina"}, {"sp": "N", "t": "Cui dono lepidum novum libellum<br>arido modo pumice expolitum?<br>Corneli, tibi; namque tu solebas<br>meas esse aliquid putare nugas,<br>iam tum cum ausus es unus Italorum<br>omne aevum tribus explicare chartis,<br>doctis, Iuppiter, et laboriosis!<br>quare habe tibi quidquid hoc libelli<br>qualecumque, quod, o patrona virgo,<br>plus uno maneat perenne saeclo.", "st": "1"}, {"sp": "N", "t": "Passer, deliciae meae puellae,<br>quicum ludere, quem in sinu tenere,<br>cui primum digitum dare adpetenti<br>et acris solet incitare morsus,<br>cum desiderio meo nitenti<br>carum nescio quid libet iocari<br>(et solaciolum sui doloris,<br>credo, ut tum gravis adquiescat ardor),<br>tecum ludere sicut ipsa possem<br>et tristis animi levare curas!<br>…<br>Tam gratum est mihi quam ferunt puellae<br>pernici aureolum fuisse malum,<br>quod zonam solvit diu ligatam.", "st": "2"}, {"sp": "N", "t": "Lugete, o Veneres Cupidinesque<br>et quantum est hominum venustiorum!<br>passer mortuus est meae puellae,<br>passer, deliciae meae puellae,<br>quem plus illa oculis suis amabat;<br>nam mellitus erat, suamque norat<br>ipsa tam bene quam puella matrem,<br>nec sese a gremio illius movebat,<br>sed circumsiliens modo huc modo illuc<br>ad solam dominam usque pipiabat.<br>qui nunc it per iter tenebricosum<br>illuc unde negant redire quemquam.<br>at vobis male sit, malae tenebrae<br>Orci, quae omnia bella devoratis;<br>tam bellum mihi passerem abstulistis.<br>o factum male! o miselle passer!<br>tua nunc opera meae puellae<br>flendo turgiduli rubent ocelli.", "st": "3"}, {"sp": "N", "t": "Phasellus ille, quem videtis, hospites,<br>ait fuisse navium celerrimus,<br>neque ullius natantis impetum trabis<br>nequisse praeterire, sive palmulis<br>opus foret volare sive linteo.<br>et hoc negat minacis Hadriatici<br>negare litus insulasve Cycladas<br>Rhodumque nobilem horridamque Thraciam<br>Propontida trucemve Ponticum sinum,<br>ubi iste post phasellus antea fuit<br>comata silva: nam Cytorio in iugo<br>loquente saepe sibilum edidit coma.<br>Amastri Pontica et Cytore buxifer,<br>tibi haec fuisse et esse cognitissima<br>ait phasellus; ultima ex origine<br>tuo stetisse dicit in cacumine,<br>tuo imbuisse palmulas in aequore,<br>et inde tot per impotentia freta<br>erum tulisse, laeva sive dextera<br>vocaret aura, sive utrumque Iuppiter<br>simul secundus incidisset in pedem;<br>neque ulla vota litoralibus diis<br>sibi esse facta, cum veniret a mari<br>novissimo hunc ad usque limpidum lacum.<br>sed haec prius fuere: nunc recondita<br>senet quiete seque dedicat tibi,<br>gemelle Castor et gemelle Castoris.", "st": "4"}, {"sp": "N", "t": "Vivamus, mea Lesbia, atque amemus,<br>rumoresque senum severiorum<br>omnes unius aestimemus assis.<br>soles occidere et redire possunt:<br>nobis, cum semel occidit brevis lux,<br>nox est perpetua una dormienda.<br>da mi basia mille, deinde centum,<br>dein mille altera, dein secunda centum,<br>deinde usque altera mille, deinde centum,<br>dein, cum milia multa fecerimus,<br>conturbabimus illa, ne sciamus,<br>aut ne quis malus invidere possit,<br>cum tantum sciat esse basiorum.", "st": "5"}, {"sp": "N", "t": "Flavi, delicias tuas Catullo,<br>ni sint inlepidae atque inelegantes,<br>velles dicere, nec tacere posses.<br>verum nescio quid febriculosi<br>scorti diligis: hoc pudet fateri.<br>nam te non viduas iacere noctes<br>nequiquam tacitum cubile clamat<br>sertis ac Syrio fragrans olivo,<br>pulvinusque peraeque et hic et ille<br>attritus, tremulique quassa lecti<br>argutatio inambulatioque.<br>nam nil stupra valet, nihil, tacere.<br>cur? non tam latera ecfututa pandas,<br>ni tu quid facias ineptiarum.<br>quare, quidquid habes boni malique,<br>dic nobis: volo te ac tuos amores<br>ad caelum lepido vocare versu.", "st": "6"}, {"sp": "N", "t": "Quaeris quot mihi basiationes<br>tuae, Lesbia, sint satis superque.<br>quam magnus numerus Libyssae harenae<br>laserpiciferis iacet Cyrenis,<br>oraclum Iovis inter aestuosi<br>et Batti veteris sacrum sepulcrum,<br>aut quam sidera multa, cum tacet nox,<br>furtivos hominum vident amores,<br>tam te basia multa basiare<br>vesano satis et super Catullo est,<br>quae nec pernumerare curiosi<br>possint nec mala fascinare lingua.", "st": "7"}, {"sp": "N", "t": "Miser Catulle, desinas ineptire,<br>et quod vides perisse perditum ducas.<br>fulsere quondam candidi tibi soles,<br>cum ventitabas quo puella ducebat<br>amata nobis quantum amabitur nulla.<br>ibi illa multa tum iocosa fiebant,<br>quae tu volebas nec puella nolebat.<br>fulsere vere candidi tibi soles.<br>nunc iam illa non vult: tu quoque, impotens, noli,<br>nec quae fugit sectare, nec miser vive,<br>sed obstinata mente perfer, obdura.<br>vale, puella! iam Catullus obdurat,<br>nec te requiret nec rogabit invitam:<br>at tu dolebis, cum rogaberis nulla.<br>scelesta, vae te! quae tibi manet vita!<br>quis nunc te adibit? cui videberis bella?<br>quem nunc amabis? cuius esse diceris?<br>quem basiabis? cui labella mordebis?<br>at tu, Catulle, destinatus obdura.", "st": "8"}, {"sp": "N", "t": "Verani, omnibus e meis amicis<br>antistans mihi milibus trecentis,<br>venistine domum ad tuos penates<br>fratresque unanimos anumque matrem?<br>venisti! o mihi nuntii beati!<br>visam te incolumem audiamque Hiberum<br>narrantem loca, facta, nationes,<br>ut mos est tuus, applicansque collum<br>iucundum os oculosque saviabor.<br>o, quantum est hominum beatiorum,<br>quid me laetius est beatiusve?", "st": "9"}, {"sp": "N", "t": "Varus me meus ad suos amores<br>visum duxerat e foro otiosum,<br>scortillum, ut mihi tunc repente visum est,<br>non sane inlepidum neque invenustum.<br>huc ut venimus, incidere nobis<br>sermones varii, in quibus, quid esset<br>iam Bithynia, quo modo se haberet,<br>ecquonam mihi profuisset aere.<br>respondi id quod erat, nihil neque ipsis<br>nec praetoribus esse nec cohorti,<br>cur quisquam caput unctius referret,<br>praesertim quibus esset irrumator<br>praetor nec faceret pili cohortem.<br>‘at certe tamen,’ inquiunt, ‘quod illic<br>natum dicitur esse comparasti,<br>ad lecticam homines.’ ego, ut puellae<br>unum me facerem beatiorem,<br>‘non,’ inquam, ‘mihi tam fuit maligne,<br>ut, provincia quod mala incidisset,<br>non possem octo homines parare rectos.’<br>at mi nullus erat neque hic neque illic<br>fractum qui veteris pedem grabati<br>in collo sibi conlocare posset.<br>hic illa, ut decuit cinaediorem,<br>‘quaeso,’ inquit, ‘mihi, mi Catulle, paulum<br>istos commoda: nam volo ad Sarapim<br>deferri.’ ‘Mane,’ inquii puellae,<br>‘istud quod modo dixeram, me habere,<br>fugit me ratio: meus sodalis<br>Cinna est Gaius; is sibi paravit.<br>verum, utrum illius an mei, quid ad me?<br>utor tam bene quam mihi pararim.<br>sed tu insulsa male et molesta vivis,<br>per quam non licet esse neglegentem.’", "st": "10"}, {"sp": "N", "t": "Furi et Aureli, comites Catulli,<br>sive in extremos penetrabit Indos,<br>litus ut longe resonante Eoa<br>tunditur unda,<br><br>sive in Hyrcanos Arabasve molles,<br>seu Sacas sagittiferosve Parthos,<br>sive quae septemgeminus colorat<br>aequora Nilus,<br><br>sive trans altas gradietur Alpes<br>Caesaris visens monimenta magni,<br>Gallicum Rhenum, horribile aequor, ulti-<br>mosque Britannos,<br><br>omnia haec, quaecumque feret voluntas<br>caelitum, temptare simul parati,<br>pauca nuntiate meae puellae<br>non bona dicta.<br><br>cum suis vivat valeatque moechis,<br>quos simul complexa tenet trecentos,<br>nullum amans vere, sed identidem omnium<br>ilia rumpens;<br><br>nec meum respectet, ut ante, amorem,<br>qui illius culpa cecidit velut prati<br>ultimi flos, praetereunte postquam<br>tactus aratro est.", "st": "11"}, {"sp": "N", "t": "Marrucine Asini, manu sinistra<br>non belle uteris in ioco atque vino:<br>tollis lintea neglegentiorum.<br>hoc salsum esse putas? fugit te, inepte!<br>quamvis sordida res et invenusta est<br>non credis mihi? crede Pollioni<br>fratri, qui tua furta vel talento<br>mutari velit; est enim leporum<br>disertus puer ac facetiarum.<br>quare aut hendecasyllabos trecentos<br>exspecta, aut mihi linteum remitte,<br>quod me non movet aestimatione,<br>verum est mnemosynum mei sodalis.<br>nam sudaria Saetaba ex Hiberis<br>miserunt mihi muneri Fabullus<br>et Veranius: haec amem necesse est<br>et Veraniolum meum et Fabullum.", "st": "12"}, {"sp": "N", "t": "Cenabis bene, mi Fabulle, apud me<br>paucis, si tibi di favent, diebus,<br>si tecum attuleris bonam atque magnam<br>cenam, non sine candida puella<br>et vino et sale et omnibus cachinnis.<br>haec si, inquam, attuleris, venuste noster<br>cenabis bene; nam tui Catulli<br>plenus sacculus est aranearum.<br>sed contra accipies meros amores<br>seu quid suavius elegantiusve est:<br>nam unguentum dabo, quod meae puellae<br>donarunt Veneres Cupidinesque,<br>quod tu cum olfacies, deos rogabis<br>totum ut te faciant, Fabulle, nasum.", "st": "13"}, {"sp": "N", "t": "Ni te plus oculis meis amarem,<br>iucundissime Calve, munere isto<br>odissem te odio Vatiniano:<br>nam quid feci ego quidve sum locutus,<br>cur me tot male perderes poetis?<br>isti di mala multa dent clienti<br>qui tantum tibi misit impiorum.<br>quod si, ut suspicor, hoc novum ac repertum<br>munus dat tibi Sulla litterator,<br>non est mi male, sed bene ac beate,<br>quod non dispereunt tui labores.<br>di magni, horribilem et sacrum libellum,<br>quem tu scilicet ad tuum Catullum<br>misti, continuo ut die periret,<br>Saturnalibus, optimo dierum!<br>non, non hoc tibi, false, sic abibit:<br>nam, si luxerit, ad librariorum<br>curram scrinia, Caesios, Aquinos,<br>Suffenum, omnia colligam venena,<br>ac te his suppliciis remunerabor.<br>vos hinc interea valete, abite<br>illuc unde malum pedem attulistis,<br>saecli incommoda, pessimi poetae.", "st": "14"}, {"sp": "N", "t": "Si qui forte mearum ineptiarum<br>lectores eritis manusque vestras<br>non horrebitis admovere nobis,<br>…", "st": "14b"}, {"sp": "N", "t": "Commendo tibi me ac meos amores,<br>Aureli. Veniam peto pudentem,<br>ut, si quicquam animo tuo cupisti<br>quod castum expeteres et integellum,<br>conserves puerum mihi pudice,<br>non dico a populo: nihil veremur<br>istos qui in platea modo huc modo illuc<br>in re praetereunt sua occupati;<br>verum a te metuo tuoque pene<br>infesto pueris bonis malisque.<br>quem tu qua libet, ut libet moveto<br>quantum vis, ubi erit foris paratum:<br>hunc unum excipio, ut puto, pudenter.<br>quod si te mala mens furorque vecors<br>in tantam impulerit, sceleste, culpam,<br>ut nostrum insidiis caput lacessas,<br>ah tum te miserum malique fati,<br>quem attractis pedibus patente porta<br>percurrent raphanique mugilesque.", "st": "15"}, {"sp": "N", "t": "Pedicabo ego vos et irrumabo,<br>Aureli pathice et cinaede Furi,<br>qui me ex versiculis meis putastis,<br>quod sunt molliculi, parum pudicum.<br>nam castum esse decet pium poetam<br>ipsum, versiculos nihil necesse est,<br>qui tum denique habent salem ac leporem,<br>si sunt molliculi ac parum pudici<br>et quod pruriat incitare possunt,<br>non dico pueris, sed his pilosis,<br>qui duros nequeunt movere lumbos.<br>vos quod milia multa basiorum<br>legistis, male me marem putatis?<br>pedicabo ego vos et irrumabo.", "st": "16"}, {"sp": "N", "t": "O Colonia, quae cupis ponte ludere longo,<br>et salire paratum habes, sed vereris inepta<br>crura ponticuli assulis stantis in redivivis,<br>ne supinus eat cavaque in palude recumbat,<br>sic tibi bonus ex tua pons libidine fiat,<br>in quo vel Salisubsili sacra suscipiantur,<br>munus hoc mihi maximi da, Colonia, risus.<br>quendam municipem meum de tuo volo ponte<br>ire praecipitem in lutum per caputque pedesque,<br>verum totius ut lacus putidaeque paludis<br>lividissima maximeque est profunda vorago.<br>insulsissimus est homo, nec sapit pueri instar<br>bimuli tremula patris dormientis in ulna:<br>cui cum sit viridissimo nupta flore puella<br>(et puella tenellulo delicatior haedo,<br>adservanda nigerrimis diligentius uvis),<br>ludere hanc sinit ut libet, nec pili facit uni,<br>nec se sublevat ex sua parte, sed velut alnus<br>in fossa Liguri iacet suppernata securi,<br>tantundem omnia sentiens quam si nulla sit usquam<br>talis iste meus stupor nil videt, nihil audit,<br>ipse qui sit, utrum sit an non sit, id quoque nescit.<br>nunc eum volo de tuo ponte mittere pronum,<br>si pote stolidum repente excitare veternum<br>et supinum animum in gravi derelinquere caeno,<br>ferream ut soleam tenaci in voragine mula.", "st": "17"}, {"sp": "N", "t": "Aureli, pater esuritionum,<br>non harum modo, sed quot aut fuerunt<br>aut sunt aut aliis erunt in annis,<br>pedicare cupis meos amores.<br>nec clam: nam simul es, iocaris una,<br>haerens ad latus omnia experiris.<br>frustra: nam insidias mihi instruentem<br>tangam te prior irrumatione.<br>atque id si faceres satur, tacerem:<br>nunc ipsum id doleo, quod esurire,<br>ah me me, puer et sitire discet.<br>quare desine, dum licet pudico,<br>ne finem facias, sed irrumatus.", "st": "21"}, {"sp": "N", "t": "Suffenus iste, Vare, quem probe nosti,<br>homo est venustus et dicax et urbanus,<br>idemque longe plurimos facit versus.<br>puto esse ego illi milia aut decem aut plura<br>perscripta, nec sic, ut fit, in palimpsesto<br>relata: chartae regiae, novi libri,<br>novi umbilici, lora, rubra membrana,<br>derecta plumbo et pumice omnia aequata.<br>haec cum legas tu, bellus ille et urbanus<br>Suffenus unus caprimulgus aut fossor<br>rursus videtur: tantum abhorret ac mutat.<br>hoc quid putemus esse? Qui modo scurra<br>aut si quid hac re tritius videbatur,<br>idem infaceto est infacetior rure<br>simul poemata attigit, neque idem unquam<br>aeque est beatus ac poema cum scribit:<br>tam gaudet in se tamque se ipse miratur.<br>nimirum idem omnes fallimur, neque est quisquam<br>quem non in aliqua re videre Suffenum<br>possis. Suus cuique attributus est error,<br>sed non videmus manticae quod in tergo est.", "st": "22"}, {"sp": "N", "t": "Furi, cui neque servus est neque arca<br>nec cimex neque araneus neque ignis,<br>verum est et pater et noverca, quorum<br>dentes vel silicem comesse possunt,<br>est pulchre tibi cum tuo parente<br>et cum coniuge lignea parentis.<br>nec mirum: bene nam valetis omnes,<br>pulchre concoquitis, nihil timetis,<br>non incendia, non graves ruinas,<br>non furta impia, non dolos veneni,<br>non casus alios periculorum.<br>atqui corpora sicciora cornu<br>aut si quid magis aridum est habetis<br>sole et frigore et esuritione.<br>quare non tibi sit bene ac beate?<br>a te sudor abest, abest saliva,<br>mucusque et mala pituita nasi.<br>hanc ad munditiem adde mundiorem,<br>quod culus tibi purior salillo est,<br>nec toto decies cacas in anno;<br>atque id durius est faba et lapillis,<br>quod tu si manibus teras fricesque,<br>non unquam digitum inquinare possis.<br>haec tu commoda tam beata, Furi,<br>noli spernere nec putare parvi,<br>et sestertia quae soles precari<br>centum desine: nam satis beatu's.", "st": "23"}, {"sp": "N", "t": "O qui flosculus es Iuventiorum,<br>non horum modo, sed quot aut fuerunt<br>aut posthac aliis erunt in annis,<br>mallem divitias Midae dedisses<br>isti cui neque servus est neque arca,<br>quam sic te sineres ab illo amari.<br>‘quid? Non est homo bellus?’ inquies. est:<br>sed bello huic neque servus est neque arca.<br>hoc tu quam libet abice elevaque:<br>nec servum tamen ille habet neque arcam.", "st": "24"}, {"sp": "N", "t": "Cinaede Thalle, mollior cuniculi capillo<br>vel anseris medullula vel imula auricilla<br>vel pene languido senis situque araneoso,<br>idemque Thalle turbida rapacior procella,<br>cum † diva mulier aries ostendit oscitantes,<br>remitte pallium mihi meum quod involasti<br>sudariumque Saetabum catagraphosque Thynos,<br>inepte, quae palam soles habere tanquam avita.<br>quae nunc tuis ab unguibus reglutina et remitte,<br>ne laneum latusculum manusque mollicellas<br>inusta turpiter tibi flagella conscribillent,<br>et insolenter aestues velut minuta magno<br>deprensa navis in mari vesaniente vento.", "st": "25"}, {"sp": "N", "t": "Furi, villula vestra non ad Austri<br>flatus opposita est neque ad Favoni<br>nec saevi Boreae aut Apeliotae,<br>verum ad milia quindecim et ducentos.<br>o ventum horribilem atque pestilentem!", "st": "26"}, {"sp": "N", "t": "Minister vetuli puer Falerni<br>inger mi calices amariores,<br>ut lex Postumiae iubet magistrae,<br>ebrioso acino ebriosioris.<br>at vos quo libet hinc abite, lymphae,<br>vini pernicies, et ad severos<br>migrate: hic merus est Thyonianus.", "st": "27"}, {"sp": "N", "t": "Pisonis comites, cohors inanis<br>aptis sarcinulis et expeditis,<br>Verani optime tuque mi Fabulle,<br>quid rerum geritis? Satisne cum isto<br>vappa frigoraque et famem tulistis?<br>ecquidnam in tabulis patet lucelli<br>expensum, ut mihi, qui meum secutus<br>praetorem refero datum lucello,<br>‘o Memmi, bene me ac diu supinum<br>tota ista trabe lentus irrumasti.’<br>sed, quantum video, pari fuistis<br>casu: nam nihilo minore verpa<br>farti estis. pete nobiles amicos.<br>at vobis mala multa di deaeque<br>dent, opprobria Romuli Remique.", "st": "28"}, {"sp": "N", "t": "Quis hoc potest videre, quis potest pati,<br>nisi impudicus et vorax et aleo,<br>Mamurram habere quod comata Gallia<br>habebat ante et ultima Britannia?<br>Cinaede Romule, haec videbis et feres?<br>et ille nunc superbus et superfluens<br>perambulabit omnium cubilia<br>ut albulus columbus aut Adoneus?<br>cinaede Romule, haec videbis et feres?<br>es impudicus et vorax et aleo.<br>eone nomine, imperator unice,<br>fuisti in ultima occidentis insula,<br>ut ista vestra diffututa mentula<br>ducenties comesset aut trecenties?<br>quid est alid sinistra liberalitas?<br>parum expatravit an parum elluatus est?<br>paterna prima lancinata sunt bona;<br>secunda praeda Pontica; inde tertia<br>Hibera, quam scit amnis aurifer Tagus.<br>nunc Galliae timetur et Britanniae.<br>quid hunc malum fovetis? aut quid hic potest<br>nisi uncta devorare patrimonia?<br>eone nomine † urbis opulentissime<br>socer generque, perdidistis omnia?", "st": "29"}, {"sp": "N", "t": "Alfene immemor atque unanimis false sodalibus,<br>iam te nil miseret, dure, tui dulcis amiculi?<br>iam me prodere, iam non dubitas fallere, perfide?<br>nec facta impia fallacum hominum caelicolis placent;<br>quae tu neglegis, ac me miserum deseris in malis.<br>eheu, quid faciant, dic, homines, cuive habeant fidem?<br>certe tute iubebas animam tradere, inique, me<br>inducens in amorem, quasi tuta omnia mi forent.<br>idem nunc retrahis te ac tua dicta omnia factaque<br>ventos irrita ferre ac nebulas aerias sinis.<br>si tu oblitus es, at di meminerunt, meminit Fides,<br>quae te ut paeniteat postmodo facti faciet tui.", "st": "30"}, {"sp": "N", "t": "Paene insularum, Sirmio, insularumque<br>ocelle, quascumque in liquentibus stagnis<br>marique vasto fert uterque Neptunus,<br>quam te libenter quamque laetus inviso,<br>vix mi ipse credens Thyniam atque Bithynos<br>liquisse campos et videre te in tuto!<br>o quid solutis est beatius curis,<br>cum mens onus reponit, ac peregrino<br>labore fessi venimus larem ad nostrum<br>desideratoque adquiescimus lecto?<br>hoc est quod unum est pro laboribus tantis.<br>salve, o venusta Sirmio, atque ero gaude;<br>gaudete vosque, o Lydiae lacus undae;<br>ridete, quidquid est domi cachinnorum.", "st": "31"}, {"sp": "N", "t": "Amabo, mea dulcis Ipsithilla,<br>meae deliciae, mei lepores,<br>iube ad te veniam meridiatum.<br>et si iusseris illud, adiuvato,<br>ne quis liminis obseret tabellam,<br>neu tibi libeat foras abire;<br>sed domi maneas paresque nobis<br>novem continuas fututiones.<br>verum, si quid ages, statim iubeto:<br>nam pransus iaceo et satur supinus<br>pertundo tunicamque palliumque.", "st": "32"}, {"sp": "N", "t": "O furum optime balneariorum<br>Vibenni pater, et cinaede fili,<br>(nam dextra pater inquinatiore,<br>culo filius est voraciore)<br>cur non exsilium malasque in oras<br>itis, quandoquidem patris rapinae<br>notae sunt populo, et natis pilosas,<br>fili, non potes asse venditare?", "st": "33"}, {"sp": "N", "t": "Dianae sumus in fide<br>puellae et pueri integri;<br>Dianam pueri integri<br>puellaeque canamus.<br><br>O Latonia, maximi<br>magna progenies Iovis,<br>quam mater prope Deliam<br>deposivit olivam,<br><br>montium domina ut fores<br>silvarumque virentium<br>saltuumque reconditorum<br>amniumque sonantum;<br><br>tu Lucina dolentibus<br>Iuno dicta puerperis,<br>tu potens Trivia et notho es<br>dicta lumine Luna.<br><br>tu cursu, dea, menstruo<br>metiens iter annuum<br>rustica agricolae bonis<br>tecta frugibus exples.<br><br>sis quocumque tibi placet<br>sancta nomine, Romulique,<br>antique ut solita es, bona<br>sospites ope gentem.", "st": "34"}, {"sp": "N", "t": "Poetae tenero, meo sodali<br>velim Caecilio, papyre, dicas,<br>Veronam veniat, Novi relinquens<br>Comi moenia Lariumque litus:<br>nam quasdam volo cogitationes<br>amici accipiat sui meique.<br>quare, si sapiet, viam vorabit,<br>quamvis candida milies puella<br>euntem revocet manusque collo<br>ambas iniciens roget morari,<br>quae nunc, si mihi vera nuntiantur,<br>illum deperit impotente amore:<br>nam quo tempore legit incohatam<br>Dindymi dominam, ex eo misellae<br>ignes interiorem edunt medullam.<br>ignosco tibi, Sapphica puella<br>Musa doctior: est enim venuste<br>Magna Caecilio incohata Mater.", "st": "35"}, {"sp": "N", "t": "Annales Volusi, cacata charta,<br>votum solvite pro mea puella:<br>nam sanctae Veneri Cupidinique<br>vovit, si sibi restitutus essem<br>desissemque truces vibrare iambos,<br>electissima pessimi poetae<br>scripta tardipedi deo daturam<br>infelicibus ustilanda lignis.<br>et hoc pessima se puella vidit<br>iocose lepide vovere divis.<br>nunc, o caeruleo creata ponto,<br>quae sanctum Idalium Uriosque apertos,<br>quaeque Ancona Cnidumque harundinosam<br>colis, quaeque Amathunta, quaeque Golgos,<br>quaeque Durrachium Hadriae tabernam,<br>acceptum face redditumque votum,<br>si non inlepidum neque invenustum est.<br>at vos interea venite in ignem,<br>pleni ruris et inficetiarum<br>Annales Volusi, cacata charta.", "st": "36"}, {"sp": "N", "t": "Salax taberna vosque contubernales,<br>a pilleatis nona fratribus pila,<br>solis putatis esse mentulas vobis,<br>solis licere quidquid est puellarum<br>confutuere et putare ceteros hircos?<br>an, continenter quod sedetis insulsi<br>centum an ducenti, non putatis ausurum<br>me una ducentos irrumare sessores?<br>atqui putate: namque totius vobis<br>frontem tabernae sopionibus scribam.<br>puella nam mi, quae meo sinu fugit,<br>amata tantum quantum amabitur nulla,<br>pro qua mihi sunt magna bella pugnata,<br>consedit istic. hanc boni beatique<br>omnes amatis, et quidem, quod indignum est,<br>omnes pusilli et semitarii moechi:<br>tu praeter omnes une de capillatis,<br>cuniculosae Celtiberiae fili,<br>Egnati, opaca quem bonum facit barba<br>et dens Hibera defricatus urina.", "st": "37"}, {"sp": "N", "t": "Male est, Cornifici, tuo Catullo,<br>male est me hercule ei et laboriose,<br>et magis magis in dies et horas.<br>quem tu, quod minimum facillimumque est,<br>qua solatus es adlocutione?<br>irascor tibi. sic meos amores?<br>paulum quid libet adlocutionis,<br>maestius lacrimis Simonideis.", "st": "38"}, {"sp": "N", "t": "Egnatius, quod candidos habet dentes,<br>renidet usque quaque. si ad rei ventum est<br>subsellium, cum orator excitat fletum,<br>renidet ille. si ad pii rogum fili<br>lugetur, orba cum flet unicum mater,<br>renidet ille. quidquid est, ubicumque est,<br>quodcumque agit, renidet. hunc habet morbum<br>neque elegantem, ut arbitror, neque urbanum.<br>quare monendum est te mihi, bone Egnati.<br>si urbanus esses aut Sabinus aut Tiburs<br>aut parcus Umber aut obesus Etruscus<br>aut Lanuvinus ater atque dentatus<br>aut Transpadanus, ut meos quoque attingam,<br>aut qui libet qui puriter lavit dentes,<br>tamen renidere usque quaque te nollem;<br>nam risu inepto res ineptior nulla est.<br>nunc Celtiber es: Celtiberia in terra,<br>quod quisque minxit, hoc sibi solet mane<br>dentem atque russam defricare gingivam,<br>ut quo iste vester expolitior dens est,<br>hoc te amplius bibisse praedicet loti.", "st": "39"}, {"sp": "N", "t": "Quaenam te mala mens, miselle Ravide,<br>agit praecipitem in meos iambos?<br>quis deus tibi non bene advocatus<br>vecordem parat excitare rixam?<br>an ut pervenias in ora vulgi?<br>quid vis? qua libet esse notus optas?<br>eris, quandoquidem meos amores<br>cum longa voluisti amare poena.", "st": "40"}, {"sp": "N", "t": "Ameana puella defututa<br>tota milia me decem poposcit,<br>ista turpiculo puella naso,<br>decoctoris amica Formiani.<br>propinqui, quibus est puella curae,<br>amicos medicosque convocate:<br>non est sana puella, nec rogare<br>qualis sit solet aes imaginosum.", "st": "41"}, {"sp": "N", "t": "Adeste, hendecasyllabi, quot estis<br>omnes undique, quotquot estis omnes.<br>iocum me putat esse moecha turpis<br>et negat mihi vestra reddituram<br>pugillaria, si pati potestis.<br>persequamur eam, et reflagitemus.<br>quae sit quaeritis? illa quam videtis<br>turpe incedere, mimice ac moleste<br>ridentem catuli ore Gallicani.<br>circumsistite eam, et reflagitate:<br>‘moecha putida, redde codicillos,<br>redde, putida moecha, codicillos.’<br>non assis facis? o lutum, lupanar,<br>aut si perditius potes quid esse.<br>sed non est tamen hoc satis putandum.<br>quod si non aliud potest, ruborem<br>ferreo canis exprimamus ore.<br>conclamate iterum altiore voce<br>‘moecha putida, redde codicillos,<br>redde, putida moecha, codicillos.’<br>sed nil proficimus, nihil movetur.<br>mutanda est ratio modusque nobis,<br>si quid proficere amplius potestis,<br>‘pudica et proba, redde codicillos.’", "st": "42"}, {"sp": "N", "t": "Salve, nec minimo puella naso<br>nec bello pede nec nigris ocellis<br>nec longis digitis nec ore sicco<br>nec sane nimis elegante lingua,<br>decoctoris amica Formiani.<br>ten provincia narrat esse bellam?<br>tecum Lesbia nostra comparatur?<br>o saeclum insapiens et infacetum!", "st": "43"}, {"sp": "N", "t": "O funde noster seu Sabine seu Tiburs<br>(nam te esse Tiburtem autumant quibus non est<br>cordi Catullum laedere: at quibus cordi est<br>quovis Sabinum pignore esse contendunt),<br>sed seu Sabine sive verius Tiburs,<br>fui libenter in tua suburbana<br>villa malamque pectore expuli tussim,<br>non immerenti quam mihi meus venter,<br>dum sumptuosas adpeto, dedit, cenas.<br>nam, Sestianus dum volo esse conviva,<br>orationem in Antium petitorem<br>plenam veneni et pestilentiae legi.<br>hic me gravido frigida et frequens tussis<br>quassavit usque dum in tuum sinum fugi<br>et me recuravi otioque et urtica.<br>quare refectus maximas tibi grates<br>ago, meum quod non es ulta peccatum.<br>nec deprecor iam, si nefaria scripta<br>Sesti recepso, quin gravedinem et tussim<br>non mi, sed ipsi Sestio ferat frigus,<br>qui tunc vocat me cum malum librum legi.", "st": "44"}, {"sp": "N", "t": "Acmen Septimius suos amores<br>tenens in gremio ‘mea,’ inquit, ‘Acme,<br>ni te perdite amo atque amare porro<br>omnes sum adsidue paratus annos<br>quantum qui pote plurimum perire,<br>solus in Libya Indiaque tosta<br>caesio veniam obvius leoni.’<br>hoc ut dixit, Amor, sinistra ut ante,<br>dextra sternuit adprobationem.<br>at Acme leviter caput reflectens<br>et dulcis pueri ebrios ocellos<br>illo purpureo ore saviata<br>‘sic,’ inquit, ‘mea vita, Septimille,<br>huic uni domino usque serviamus,<br>ut multo mihi maior acriorque<br>ignis mollibus ardet in medullis.’<br>hoc ut dixit, Arnor, sinistra ut ante,<br>dextra sternuit adprobationem.<br>nunc ab auspicio bono profecti<br>mutuis animis amant amantur.<br>unam Septimius misellus Acmen<br>mavult quam Syrias Britanniasque:<br>uno in Septimio fidelis Acme<br>facit delicias libidinesque.<br>quis ullos homines beatiores<br>vidit, quis Venerem auspicatiorem?", "st": "45"}, {"sp": "N", "t": "Iam ver egelidos refert tepores,<br>iam caeli furor aequinoctialis<br>iucundis Zephyri silescit auris.<br>linquantur Phrygii, Catulle, campi<br>Nicaeaeque ager uber aestuosae:<br>ad claras Asiae volemus urbes.<br>iam mens praetrepidans avet vagari,<br>iam laeti studio pedes vigescunt.<br>o dulces comitum valete coetus,<br>longe quos simul a domo profectos<br>diversae variae viae reportant.", "st": "46"}, {"sp": "N", "t": "Porci et Socration, duae sinistrae<br>Pisonis, scabies famesque mundi,<br>vos Veraniolo meo et Fabullo<br>verpus praeposuit Priapus ille?<br>vos convivia lauta sumptuose<br>de die facitis? mei sodales<br>quaerunt in trivio vocationes?", "st": "47"}, {"sp": "N", "t": "Mellitos oculos tuos, Iuventi,<br>siquis me sinat usque basiare,<br>usque ad milia basiem trecenta,<br>nec unquam videar satur futurus,<br>non si densior aridis aristis<br>sit nostrae seges osculationis.", "st": "48"}, {"sp": "N", "t": "Disertissime Romuli nepotum,<br>quot sunt quotque fuere, Marce Tulli,<br>quotque post aliis erunt in annis,<br>gratias tibi maximas Catullus<br>agit pessimus omnium poeta,<br>tanto pessimus omnium poeta<br>quanto tu optimus omnium patronus.", "st": "49"}, {"sp": "N", "t": "Hesterno, Licini, die otiosi<br>multum lusimus in meis tabellis,<br>ut convenerat esse delicatos.<br>scribens versiculos uterque nostrum<br>ludebat numero modo hoc modo illoc,<br>reddens mutua per iocum atque vinum.<br>atque illinc abii tuo lepore<br>incensus, Licini, facetiisque,<br>ut nec me miserum cibus iuvaret,<br>nec somnus tegeret quiete ocellos,<br>sed toto indomitus furore lecto<br>versarer cupiens videre lucem,<br>ut tecum loquerer simulque ut essem.<br>at defessa labore membra postquam<br>semimortua lectulo iacebant,<br>hoc, iucunde, tibi poema feci,<br>ex quo perspiceres meum dolorem.<br>nunc audax cave sis, precesque nostras,<br>oramus, cave despuas, ocelle,<br>ne poenas Nemesis reposcat a te.<br>est vehemens dea: laedere hanc caveto.", "st": "50"}, {"sp": "N", "t": "Ille mi par esse deo videtur,<br>ille, si fas est, superare divos<br>qui sedens adversus identidem te<br>spectat et audit<br><br>dulce ridentem, misero quod omnis<br>eripit sensus mihi: nam simul te,<br>Lesbia, adspexi, nihil est super mi<br>…<br><br>lingua sed torpet, tenuis sub artus<br>flamma demanat, sonitu suopte<br>tintinant aures, gemina teguntur<br>lumina nocte.<br><br>otium, Catulle, tibi molestum est:<br>otio exsultas nimiumque gestis.<br>otium et reges prius et beatas<br>perdidit urbes.", "st": "51"}, {"sp": "N", "t": "Quid est, Catulle? quid moraris emori?<br>sella in curuli struma Nonius sedet,<br>per consulatum perierat Vatinius:<br>quid est, Catulle? quid moraris emori?", "st": "52"}, {"sp": "N", "t": "Risi nescio quem modo e corona,<br>qui, cum mirifice Vatiniana<br>meus crimina Calvus explicasset,<br>admirans ait haec manusque tollens<br>‘di magni, salaputium disertum!’", "st": "53"}, {"sp": "N", "t": "Othonis caput oppido est pusillum,<br>…<br>et eri rustica semilauta crura,<br>subtile et leve peditum Libonis,<br>…<br>si non omnia, displicere vellem<br>tibi et Fuficio, seni recocto<br>…<br>irascere iterum meis iambis<br>immerentibus, unice imperator.", "st": "54"}, {"sp": "N", "t": "Oramus, si forte non molestum est,<br>demonstres ubi sint tuae tenebrae.<br>te campo quaesivimus minore,<br>te in circo, te in omnibus libellis,<br>te in templo summi Iovis sacrato.<br>in Magni simul ambulatione<br>femellas omnes, amice, prendi,<br>quas vultu vidi tamen serenas.<br>† A velte sic ipse flagitabam:<br>‘camerium mihi, pessimae puellae!’<br>quaedam inquit nudum † reduc †<br>‘en hic in roseis latet papillis.’<br>sed te iam ferre Herculi labos est:<br>Non custos si fingar ille Cretum,<br>non si Pegaseo ferar volatu,<br>non Ladas ego pinnipesve Perseus,<br>non Rhesi niveae citaeque bigae:<br>adde huc plumipedes volatilesque,<br>ventorumque simul require cursum,<br>quos vinctos, Cameri, mihi dicares:<br>defessus tamen omnibus medullis<br>et multis langoribus peresus<br>essem te mihi, amice, quaeritando.<br>tanto ten fastu negas, amice?<br>dic nobis ubi sis futurus, ede<br>audacter, committe, crede luci.<br>nunc te lacteolae tenent puellae?<br>si linguam clauso tenes in ore,<br>fructus proicies amoris omnes:<br>verbosa gaudet Venus loquella.<br>vel vi vis, licet obseres palatum,<br>dum veri sis particeps amoris.", "st": "55"}, {"sp": "N", "t": "O rem ridiculam, Cato, et iocosam<br>dignamque auribus et tuo cachinno.<br>ride, quidquid amas, Cato, Catullum:<br>res est ridicula et nimis iocosa.<br>deprendi modo pupulum puellae<br>trusantem: hunc ego, si placet Dionae,<br>pro telo rigida mea cecidi.", "st": "56"}, {"sp": "N", "t": "Pulchre convenit improbis cinaedis,<br>Mamurrae pathicoque Caesarique.<br>nec mirum: maculae pares utrisque,<br>urbana altera et illa Formiana,<br>impressae resident nec eluentur:<br>morbosi pariter gemelli utrique,<br>uno in lecticulo erudituli ambo,<br>non hic quam ille magis vorax adulter,<br>rivales socii puellularum:<br>pulchre convenit improbis cinaedis.", "st": "57"}, {"sp": "N", "t": "Caeli, Lesbia nostra, Lesbia illa,<br>illa Lesbia, quam Catullus unam<br>plus quam se atque suos amavit omnes,<br>nunc in quadriviis et angiportis<br>glubit magnanimi Remi nepotes.", "st": "58"}, {"sp": "N", "t": "Bononiensis Rufa Rufulum fellat,<br>uxor Meneni, saepe quam in sepulcretis<br>vidistis ipso rapere de rogo cenam,<br>cum devolutum ex igne prosequens panem<br>ab semiraso tunderetur ustore.", "st": "59"}, {"sp": "N", "t": "Num te leaena montibus Libystinis<br>aut Scylla latrans infima inguinum parte<br>tam mente dura procreavit ac taetra,<br>ut supplicis vocem in novissimo casu<br>contemptam haberes, ah nimis fero corde?", "st": "60"}, {"sp": "N", "t": "Collis o Heliconii<br>cultor, Uraniae genus,<br>qui rapis teneram ad virum<br>virginem, o Hymenaee Hymen,<br>o Hymen Hymenaee,<br><br>cinge tempora floribus<br>suave olentis amaraci,<br>flammeum cape, laetus huc,<br>huc veni niveo gerens<br>luteum pede soccum,<br><br>excitusque hilari die<br>nuptialia concinens<br>voce carmina tinnula<br>pelle humum pedibus, manu<br>pineam quate taedam.<br><br>namque Vinia Manilo,<br>qualis Idalium colens<br>venit ad Phrygium Venus<br>iudicem, bona cum bona<br>nubet alite virgo,<br><br>floridis velut enitens<br>myrtus Asia ramulis,<br>quos hamadryades deae<br>ludicrum sibi rosido<br>nutriunt umore.<br><br>quare age huc aditum ferens<br>perge linquere Thespiae<br>rupis Aonios specus,<br>nympha quos super irrigat<br>frigerans Aganippe,<br><br>ac domum dominam voca<br>coniugis cupidam novi,<br>mentem amore revinciens<br>ut tenax hedera huc et huc<br>arborem implicat errans.<br><br>vosque item simul, integrae<br>virgines, quibus advenit<br>par dies, agite in modum<br>dicite, ‘o Hymenaee Hymen,<br>o Hymen Hymenaee.’<br><br>ut libentius, audiens<br>se citarier ad suum<br>munus, huc aditum ferat<br>dux bonae Veneris, boni<br>coniugator amoris.", "st": "61"}, {"sp": "N", "t": "quis deus magis anxiis<br>est petendus amantibus?<br>quem colent homines magis<br>caelitum? o Hymenaee Hymen,<br>o Hymen Hymenaee.<br><br>te suis tremulus parens<br>invocat, tibi virgines<br>zonula solvunt sinus,<br>te timens cupida novus<br>captat aure maritus.<br><br>tu fero iuveni in manus<br>floridam ipse puellulam<br>dedis a gremio suae<br>matris, o Hymenaee Hymen,<br>o Hymen Hymenaee.<br><br>nil potest sine te Venus<br>fama quod bona comprobet<br>commodi capere: at potest<br>te volente. quis huic deo<br>compararier ausit?<br><br>nulla quit sine te domus<br>liberos dare, nec parens<br>stirpe nitier: at potest<br>te volente. quis huic deo<br>compararier ausit?<br><br>quae tuis careat sacris<br>non queat dare praesides<br>terra finibus: at queat<br>te volente. quis huic deo<br>compararier ausit?", "st": "61"}, {"sp": "N", "t": "claustra pandite ianuae,<br>virgo adest. viden ut faces<br>splendidas quatiunt comas?<br>…<br>…<br><br>…<br>…<br>tardet ingenuus pudor:<br>quem tamen magis audiens<br>flet quod ire necesse est.<br><br>flere desine. Non tibi, Au-<br>runculeia, periculum est<br>ne qua femina pulchrior<br>clarum ab Oceano diem<br>viderit venientem.<br><br>talis in vario solet<br>divitis domini hortulo<br>stare flos hyacinthinus.<br>sed moraris, abit dies:<br>prodeas, nova nupta.<br><br>prodeas, nova nupta, si<br>iam videtur, et audias<br>nostra verba. vide ut faces<br>aureas quatiunt comas:<br>prodeas, nova nupta.<br><br>non tuus levis in mala<br>deditus vir adultera<br>probra turpia persequens<br>a tuis teneris volet<br>secubare papillis,<br><br>lenta quin velut adsitas<br>vitis implicat arbores,<br>implicabitur in tuum<br>complexum. Sed abit dies:<br>prodeas, nova nupta.<br><br>o cubile quod omnibus<br>…<br>…<br>…<br>candido pede lecti,<br><br>quae tuo veniunt ero,<br>quanta gaudia, quae vaga<br>nocte, quae medio die<br>gaudeat! sed abit dies:<br>Prodeas, nova nupta.", "st": "61"}, {"sp": "N", "t": "tollite, o pueri, faces:<br>flammeum video venire.<br>ite, concinite in modum<br>‘o Hymen Hymenaee io,<br>o Hymen Hymenaee.’<br><br>ne diu taceat procax<br>fescennina iocatio,<br>nec nuces pueris neget<br>desertum domini audiens<br>concubinus amorem.<br><br>da nuces pueris, iners<br>concubine: satis diu<br>lusisti nucibus: libet<br>iam servire Talasio.<br>concubine, nuces da.<br><br>sordebant tibi vilicae,<br>concubine, hodie atque heri:<br>nunc tuum cinerarius<br>tondet os. miser ah miser<br>concubine, nuces da.<br><br>diceris male te a tuis<br>unguentate glabris marite<br>abstinere: sed abstine.<br>o Hymen Hymenaee io,<br>o Hymen Hymenaee.<br><br>scimus haec tibi quae licent<br>sola cognita: sed marito<br>ista non eadem licent.<br>o Hymen Hymenaee io,<br>o Hymen Hymenaee.", "st": "61"}, {"sp": "N", "t": "nupta, tu quoque quae tuus<br>vir petet cave ne neges,<br>ne petitum aliunde eat.<br>o Hymen Hymenaee io,<br>o Hymen Hymenaee.<br><br>en tibi domus ut potens<br>et beata viri tui:<br>quae tibi sine serviat<br>(o Hymen Hymenaee io,<br>o Hymen Hymenaee).<br><br>usque dum tremulum movens<br>cana tempus anilitas<br>omnia omnibus adnuit.<br>o Hymen Hymenaee io,<br>o Hymen Hymenaee.<br><br>transfer omine cum bono<br>limen aureolos pedes,<br>rasilemque subi forem.<br>o Hymen Hymenaee io,<br>o Hymen Hymenaee.<br><br>adspice unus ut accubans<br>vir tuus Tyrio in toro<br>totus immineat tibi.<br>o Hymen Hymenaee io,<br>o Hymen Hymenaee.<br><br>illi non minus ac tibi<br>pectore uritur intimo<br>flamma, sed penite magis<br>o Hymen Hymenaee io,<br>o Hymen Hymenaee.<br><br>mitte bracchiolum teres,<br>praetextate, puellulae:<br>iam cubile adeat viri.<br>o Hymen Hymenaee io,<br>o Hymen Hymenaee.<br><br>o bonae senibus viris<br>cognitae bene feminae,<br>conlocate puellulam.<br>o Hymen Hymenaee io,<br>o Hymen Hymenaee.", "st": "61"}, {"sp": "N", "t": "iam licet venias, marite:<br>uxor in thalamo tibi est<br>ore floridulo nitens<br>alba parthenice velut<br>luteumve papaver.<br><br>at, marite, (ita me iuvent<br>caelites) nihilo minus<br>pulcher es, neque te Venus<br>neglegit. sed abit dies:<br>perge, ne remorare.<br><br>non diu remoratus es,<br>iam venis. bona te Venus<br>iuverit, quoniam palam<br>quod cupis cupis et bonum<br>non abscondis amorem.<br><br>ille pulveris Africi<br>siderumque micantium<br>subducat numerum prius,<br>qui vestri numerare vult<br>multa milia ludi.<br><br>ludite ut libet, et brevi<br>liberos date. non decet<br>tam vetus sine liberis<br>nomen esse, sed indidem<br>semper ingenerari.<br><br>Torquatus volo parvulus<br>matris e gremio suae<br>porrigens teneras manus<br>dulce rideat ad patrem<br>semihiante labello.<br><br>sit suo similis patri<br>Manlio et facile insciis<br>noscitetur ab omnibus<br>et pudicitiam suae<br>matris indicet ore.<br><br>talis illius a bona<br>matre laus genus adprobet<br>qualis unica ab optima<br>matre Telemacho manet<br>fama Penelopeo.<br><br>claudite ostia, virgines:<br>lusimus satis. at, boni<br>coniuges, bene vivite et<br>munere adsiduo valentem<br>exercete iuventam.", "st": "61"}, {"sp": "N", "t": "Vesper adest: iuvenes, consurgite: vesper Olympo<br>exspectata diu vix tandem lumina tollit.<br>surgere iam tempus, iam pinguis linquere mensas;<br>iam veniet virgo, iam dicetur hymenaeus.<br>Hymen O Hymenaee, Hymen ades O Hymenaee.", "st": "62"}, {"sp": "N", "t": "cernitis, innuptae, iuvenes? consurgite contra:<br>nimirum Oetaeos ostendit Noctifer ignes.<br>sic certe est: viden ut perniciter exsiluere?<br>non temere exsiluere; canent quod vincere par est.<br>Hymen O Hymenaee, Hymen ades O Hymenaee.", "st": "62"}, {"sp": "N", "t": "non facilis nobis, aequales, palma parata est:<br>adspicite, innuptae secum ut meditata requirunt.<br>non frustra meditantur; habent memorabile quod sit.<br>nec mirum, penitus quae tota mente laborant.<br>nos alio mentes, alio divisimus aures:<br>iure igitur vincemur; amat victoria curam.<br>quare nunc animos saltem convertite vestros:<br>dicere iam incipient, iam respondere decebit.<br>Hymen o Hymenaee, Hymen ades o Hymenaee.", "st": "62"}, {"sp": "N", "t": "Hespere, qui caelo fertur crudelior ignis?<br>qui natam possis complexu avellere matris,<br>complexu matris retinentem avellere natam<br>et iuveni ardenti castam donare puellam.<br>quid faciunt hostes capta crudelius urbe?<br>Hymen o Hymenaee, Hymen ades o Hymenaee.", "st": "62"}, {"sp": "N", "t": "Hespere, qui caelo lucet iucundior ignis?<br>qui desponsa tua firmes conubia flamma,<br>quae pepigere viri, pepigerunt ante parentes,<br>nec iunxere prius quam se tuus extulit ardor.<br>quid datur a divis felici optatius hora?<br>Hymen o Hymenaee, Hymen ades o Hymenaee.", "st": "62"}, {"sp": "N", "t": "Hesperus e nobis, aequales, abstulit unam<br>…", "st": "62"}, {"sp": "N", "t": "namque tuo adventu vigilat custodia semper.<br>nocte latent fures, quos idem saepe revertens,<br>Hespere, mutato comprendis nomine eosdem.<br>at libet innuptis ficto te carpere questu.<br>quid tum, si carpunt tacita quem mente requirunt?<br>Hymen o Hymenaee, Hymen ades o Hymenaee.", "st": "62"}, {"sp": "N", "t": "ut flos in saeptis secretus nascitur hortis,<br>ignotus pecori, nullo convulsus aratro,<br>quem mulcent aurae, firmat sol, educat imber,<br>multi illum pueri, multae optavere puellae;<br>idem cum tenui carptus defloruit ungui,<br>nulli illum pueri, nullae optavere puellae:<br>sic virgo, dum intacta manet, dum cara suis est;<br>cum castum amisit polluto corpore florem,<br>nec pueris iucunda manet nec cara puellis.<br>Hymen o Hymenaee, Hymen ades o Hymenaee.", "st": "62"}, {"sp": "N", "t": "ut vidua in nudo vitis quae nascitur arvo<br>nunquam se extollit, nunquam mitem educat uvam,<br>sed tenerum prono deflectens pondere corpus<br>iam iam contingit summum radice flagellum,<br>hanc nulli agricolae, nulli accoluere iuvenci;<br>at si forte eadem est ulmo coniuncta marito,<br>multi illam agricolae, multi accoluere iuvenci:<br>sic virgo, dum intacta manet, dum inculta senescit;<br>cum par conubium maturo tempore adepta est,<br>cara viro magis et minus est invisa parenti.", "st": "62"}, {"sp": "N", "t": "et tu ne pugna cum tali coniuge, virgo.<br>non aequum est pugnare, pater cui tradidit ipse,<br>ipse pater cum matre, quibus parere necesse est.<br>virginitas non tota tua est, ex parte parentum est:<br>tertia pars patri, pars est data tertia matri,<br>tertia sola tua est. noli pugnare duobus,<br>qui genero sua iura simul cum dote dederunt.<br>Hymen o Hymenaee, Hymen ades o Hymenaee.", "st": "62"}, {"sp": "N", "t": "Super alta vectus Attis celeri rate maria<br>Phrygium ut nemus citato cupide pede tetigit<br>adiitque opaca silvis redimita loca deae,<br>stimulatus ibi furenti rabie, vagus animis<br>devolvit ili acuto sibi pondera silice.<br>itaque ut relicta sensit sibi membra sine viro,<br>etiam recente terrae sola sanguine maculans<br>niveis citata cepit manibus leve typanum,<br>typanum, tubam Cybelles, tua, mater, initia,<br>quatiensque terga tauri teneris cava digitis<br>canere haec suis adorta est tremebunda comitibus<br>‘agite ite ad alta, Gallae, Cybeles nemora simul,<br>simul ite, Dindymenae dominae vaga pecora,<br>aliena quae petentes velut exsules loca<br>sectam meam exsecutae duce me mihi comites<br>rapidum salum tulistis truculentaque pelagi<br>et corpus evirastis Veneris nimio odio,<br>hilarate erae citatis erroribus animum.<br>mora tarda mente cedat; simul ite, sequimini<br>Phrygiam ad domum Cybelles, Phrygia ad nemora deae,<br>ubi cymbalum sonat vox, ubi tympana reboant,<br>tibicen ubi canit Phryx curvo grave calamo,<br>ubi capita maenades vi iaciunt hederigerae,<br>ubi sacra sancta acutis ululatibus agitant,<br>ubi suevit illa divae volitare vaga cohors,<br>quo nos decet citatis celerare tripudiis.’", "st": "63"}, {"sp": "N", "t": "simul haec comitibus Attis cecinit notha mulier,<br>thiasus repente linguis trepidantibus ululat,<br>leve tympanum remugit, cava cymbala recrepant,<br>viridem citus adit Idam properante pede chorus.<br>furibunda simul anhelans vaga vadit animam agens<br>comitata tympano Attis per opaca nemora dux,<br>veluti iuvenca vitans onus indomita iugi:<br>rapidae ducem secuntur Gallae properipedem.<br>itaque, ut domum Cybelles tetigere lassulae,<br>nimio e labore somnum capiunt sine Cerere.<br>piger his labante langore oculos sopor operit:<br>abit in quiete molli rabidus furor animi.", "st": "63"}, {"sp": "N", "t": "sed ubi oris aurei Sol radiantibus oculis<br>lustravit aethera album, sola dura, mare ferum,<br>pepulitque noctis umbras vegetis sonipedibus,<br>ibi Somnus excitam Attin fugiens citus abiit:<br>trepidante eum recepit dea Pasithea sinu.<br>ita de quiete molli rapida sine rabie<br>simul ipsa pectore Attis sua facta recoluit,<br>liquidaque mente vidit sine quis ubique foret,<br>animo aestuante rusum reditum ad vada tetulit.<br>ibi maria vasta visens lacrimantibus oculis<br>patriam adlocuta maesta est ita voce miseriter:", "st": "63"}, {"sp": "N", "t": "‘patria o mei creatrix, patria o mea genetrix,<br>ego quam miser relinquens, dominos ut erifugae<br>famuli solent, ad Idae tetuli nemora pedem,<br>ut apud nivem et ferarum gelida stabula forem<br>et earum omnia adirem furibunda latibula,<br>ubinam aut quibus locis te positam, patria, reor?<br>cupit ipsa pupula ad te sibi derigere aciem,<br>rabie fera carens dum breve tempus animus est.<br>egone a mea remota haec ferar in nemora domo?<br>patria, bonis, amicis, genitoribus abero?<br>abero foro, palaestra, stadio, et gymnasiis?<br>miser ah miser, querendum est etiam atque etiam, anime.<br>quod enim genus figurae est ego non quod obierim?<br>ego mulier, ego adulescens, ego ephebus, ego puer,<br>ego gymnasi fui flos, ego eram decus olei:<br>mihi ianuae frequentes, mihi limina tepida,<br>mihi floridis corollis redimita domus erat,<br>linquendum ubi esset orto mihi sole cubiculum.<br>ego nunc deum ministra et Cybeles famula ferar?<br>ego maenas, ego mei pars, ego vir sterilis ero?<br>ego viridis algida Idae nive amicta loca colam?<br>ego vitam agam sub altis Phrygiae columinibus,<br>ubi cerva silvicultrix, ubi aper nemorivagus?<br>iam iam dolet quod egi, iam iamque paenitet.’", "st": "63"}, {"sp": "N", "t": "roseis ut huic labellis sonitus citus abiit<br>geminas deorum ad aures nova nuntia referens,<br>ibi iuncta iuga resoluens Cybele leonibus<br>laevumque pecoris hostem stimulans ita loquitur.<br>‘Agedum,’ inquit, ‘age ferox i, fac ut hunc furor agitet,<br>fac uti furoris ictu reditum in nemora ferat,<br>mea libere nimis qui fugere imperia cupit.<br>age caede terga cauda, tua verbera patere,<br>fac cuncta mugienti fremitu loca retonent,<br>rutilam ferox torosa cervice quate iubam.’<br>ait haec minax Cybelle religatque iuga manu.<br>ferus ipse sese adhortans rabidum incitat animo,<br>vadit, fremit, refringit virgulta pede vago.<br>at ubi umida albicantis loca litoris adiit<br>tenerumque vidit Attin prope marmora pelagi,<br>facit impetum: ille demens fugit in nemora fera:<br>ibi semper omne vitae spatium famula fuit.", "st": "63"}, {"sp": "N", "t": "dea magna, dea Cybelle, dea domina Dindymi,<br>procul a mea tuus sit furor omnis, era, domo:<br>alios age incitatos, alios age rabidos.", "st": "63"}, {"sp": "N", "t": "Peliaco quondam prognatae vertice pinus<br>dicuntur liquidas Neptuni nasse per undas<br>Phasidos ad fluctus et fines Aeeteos,<br>cum lecti iuvenes, Argivae robora pubis,<br>auratam optantes Colchis avertere pellem<br>ausi sunt vada salsa cita decurrere puppi,<br>caerula verrentes abiegnis aequora palmis.<br>diva quibus retinens in summis urbibus arces<br>ipsa levi fecit volitantem flamine currum,<br>pinea coniungens inflexae texta carinae.<br>illa rudem cursu prima imbuit Amphitriten.<br>quae simul ac rostro ventosum proscidit aequor<br>tortaque remigio spumis incanduit unda,<br>emersere freti candenti e gurgite vultus<br>aequoreae monstrum Nereides admirantes.<br>illa, siqua alia, viderunt luce marinas<br>mortales oculis nudato corpore nymphas<br>nutricum tenus exstantes e gurgite cano.<br>tum Thetidis Peleus incensus fertur amore,<br>tum Thetis humanos non despexit hymenaeos,<br>tum Thetidi pater ipse iugandum Pelea sensit.<br>o nimis optato saeclorum tempore nati<br>heroes, salvete, deum genus, o bona matrum<br>progenies, salvete iterum …<br>vos ego saepe meo, vos carmine compellabo,<br>teque adeo eximie taedis felicibus aucte<br>Thessaliae columen Peleu, cui Iuppiter ipse,<br>ipse suos divum genitor concessit amores.<br>tene Thetis tenuit pulcherrirma Nereine?<br>tene suam Tethys concessit ducere neptem<br>Oceanusque, mari totum qui amplectitur orbem?", "st": "64"}, {"sp": "N", "t": "quae simul optatae finito tempore luces<br>advenere, domum conventu tota frequentat<br>Thessalia, oppletur laetanti regia coetu:<br>dona ferunt prae se, declarant gaudia vultu.<br>deseritur Cieros, linquunt Phthiotica Tempe<br>Crannonisque domos ac moenia Larisaea,<br>Pharsalum coeunt, Pharsalia tecta frequentant.<br>rura colit nemo, mollescunt colla iuvencis,<br>non humilis curvis purgatur vinea rastris,<br>non glaebam prono convellit vomere taurus,<br>non falx attenuat frondatorum arboris umbram,<br>squalida desertis robigo infertur aratris.<br>ipsius at sedes, quacumque opulenta recessit<br>regia, fulgenti splendent auro atque argento.<br>candet ebur soliis, conlucent pocula mensae,<br>tota domus gaudet regali splendida gaza.<br>pulvinar vero divae geniale locatur<br>sedibus in mediis, Indo quod dente politum<br>tincta tegit roseo conchyli purpura fuco.", "st": "64"}, {"sp": "N", "t": "haec vestis priscis hominum variata figuris<br>heroum mira virtutes indicat arte.<br>namque fluentisono prospectans litore Diae<br>Thesea cedentem celeri cum classe tuetur<br>indomitos in corde gerens Ariadna furores,<br>necdum etiam sese quae visit visere credit,<br>ut pote fallaci quae tunc primum excita somno<br>desertam in sola miseram se cernat harena.<br>immemor at iuvenis fugiens pellit vada remis,<br>irrita ventosae linquens promissa procellae.<br>quem procul ex alga maestis Minois ocellis<br>saxea ut effigies bacchantis prospicit, eheu,<br>prospicit et magnis curarum fluctuat undis,<br>non flavo retinens subtilem vertice mitram,<br>non contecta levi velatum pectus amictu,<br>non tereti strophio lactentis vincta papillas,<br>omnia quae toto delapsa e corpore passim<br>ipsius ante pedes fluctus salis adludebant.<br>sic neque tum mitrae neque tum fluitantis amictus<br>illa vicem curans toto ex te pectore, Theseu,<br>toto animo, tota pendebat perdita mente.<br>ah misera, adsiduis quam luctibus exsternavit<br>spinosas Erycina serens in pectore curas<br>illa tempestate, ferox quo ex tempore Theseus<br>egressus curvis e litoribus Piraei<br>attigit iniusti regis Gortynia tecta.", "st": "64"}, {"sp": "N", "t": "nam perhibent olim crudeli peste coactam<br>Androgeoneae poenas exsolvere caedis<br>electos iuvenes simul et decus innuptarum<br>Cecropiam solitam esse dapem dare Minotauro.<br>quis angusta malis cum moenia vexarentur,<br>ipse suum Theseus pro caris corpus Athenis<br>proicere optavit potius quam talia Cretam<br>funera Cecropiae nec funera portarentur.<br>atque ita nave levi nitens ac lenibus auris<br>magnanimum ad Minoa venit sedesque superbas.<br>hunc simul ac cupido conspexit lumine virgo<br>regia, quam suavis exspirans castus odores<br>lectulus in molli complexu matris alebat,<br>quales Eurotae progignunt flumina myrtos<br>aurave distinctos educit verna colores,<br>non prius ex illo flagrantia declinavit<br>lumina quam cuncto concepit corpore flammam<br>funditus atque imis exarsit tota medullis.<br>heu misere exagitans immiti corde furores,<br>sancte puer, curis hominum qui gaudia misces,<br>quaeque regis Golgos quaeque Idalium frondosum,<br>qualibus incensam iactastis mente puellam<br>fluctibus in flavo saepe hospite suspirantem!<br>quantos illa tulit languenti corde timores,<br>quanto saepe magis fulgore expalluit auri,<br>cum saevum cupiens contra contendere monstrum<br>aut mortem appeteret Theseus aut praemia laudis.", "st": "64"}, {"sp": "N", "t": "non ingrata tamen frustra munuscula divis<br>promittens tacito succendit vota labello.<br>nam velut in summo quatientem bracchia Tauro<br>quercum aut conigeram sudanti cortice pinum<br>indomitus turbo contorquens flamine robur<br>eruit (illa procul radicitus exturbata<br>prona cadit, † lateque cum eius obvia frangens),<br>sic domito saevum prostravit corpore Theseus<br>nequiquam vanis iactantem cornua ventis.<br>inde pedem sospes multa cum laude reflexit<br>errabunda regens tenui vestigia filo,<br>ne labyrintheis e flexibus egredientem<br>tecti frustraretur inobservabilis error.", "st": "64"}, {"sp": "N", "t": "sed quid ego a primo digressus carmine plura<br>commemorem, ut linquens genitoris filia vultum,<br>ut consanguineae complexum, ut denique matris,<br>quae misera in gnata deperdita laetabatur,<br>omnibus his Thesei dulcem praeoptarit amorem,<br>aut ut vecta rati spumosa ad litora Diae<br>venerit, aut ut eam devinctam lumina somno<br>liquerit immemori discedens pectore coniunx?<br>saepe illam perhibent ardenti corde furentem<br>clarisonas imo fudisse ex pectore voces,<br>ac tum praeruptos tristem conscendere montes<br>unde aciem in pelagi vastos protenderet aestus,<br>tum tremuli salis adversas procurrere in undas<br>mollia nudatae tollentem tegmina surae,<br>atque haec extremis maestam dixisse querelis,<br>frigidulos udo singultus ore cientem:", "st": "64"}, {"sp": "N", "t": "‘sicine me patriis avectam, perfide, ab aris,<br>perfide, deserto liquisti in litore, Theseu?<br>sicine discedens neglecto numine divum<br>immernor ah devota domum periuria portas?<br>nullane res potuit crudelis flectere mentis<br>consilium? tibi nulla fuit clementia praesto<br>immite ut nostri vellet miserescere pectus?<br>at non haec quondam blanda promissa dedisti<br>voce mihi, non haec miserae sperare iubebas,<br>sed conubia laeta, sed optatos hymenaeos:<br>quae cuncta aerii discerpunt irrita venti.<br>nunc iam nulla viro iuranti femina credat,<br>nulla viri speret sermones esse fideles:<br>quis dum aliquid cupiens animus praegestit apisci,<br>nil metuunt iurare, nihil promittere parcunt:<br>sed simul ac cupidae mentis satiata libido est,<br>dicta nihil meminere, nihil periuria curant.<br>certe ego te in medio versantem turbine leti<br>eripui et potius germanum amittere crevi<br>quam tibi fallaci supremo in tempore deessem:<br>pro quo dilaceranda feris dabor alitibusque<br>praeda neque iniecta tumulabor mortua terra.<br>quaenam te genuit sola sub rupe leaena,<br>quod mare conceptum spumantibus exspuit undis.<br>quae Syrtis, quae Scylla rapax, quae vasta Charybdis,<br>talia qui reddis pro dulci praemia vita?<br>si tibi non cordi fuerant conubia nostra,<br>saeva quod horrebas prisci praecepta parentis,<br>at tamen in vestras potuisti ducere sedes<br>quae tibi iucundo famularer serva labore<br>candida permulcens liquidis vestigia lymphis<br>purpureave tuum consternens veste cubile.", "st": "64"}, {"sp": "N", "t": "sed quid ego ignaris nequiquam conqueror auris<br>exsternata malo, quae nullis sensibus auctae<br>nec missas audire queunt nec reddere voces?<br>ille autem prope iam mediis versatur in undis,<br>nec quisquam adparet vacua mortalis in alga.<br>sic nimis insultans extremo tempore saeva<br>fors etiam nostris invidit questibus auris.<br>Iuppiter omnipotens, utinam ne tempore primo<br>Gnosia Cecropiae tetigissent litora puppes,<br>indomito nec dira ferens stipendia tauro<br>perfidus in Creta religasset navita funem,<br>nec malus hic celans dulci crudelia forma<br>consilia in nostris requiesset sedibus hospes!<br>nam quo me referam? quali spe perdita nitor?<br>Idaeosne petam montes? ah, gurgite lato<br>discernens ponti truculentum ubi dividit aequor?<br>an patris auxilium sperem, quemne ipsa reliqui<br>respersum iuvenem fraterna caede secuta?<br>coniugis an fido consoler memet amore,<br>quine fugit lentos incurvans gurgite remos?<br>praeterea nullo litus, sola insula, tecto,<br>nec patet egressus pelagi cingentibus undis:<br>nulla fugae ratio, nulla spes: omnia muta,<br>omnia sunt deserta, ostentant omnia letum.<br>non tamen ante mihi languescent lumina morte,<br>nec prius a fesso secedent corpore sensus<br>quam iustam a divis exposcam prodita multam<br>caelestumque fidem postrema comprecer hora.<br>quare, facta virum multantes vindice poena<br>Eumenides, quibus anguino redimita capillo<br>frons exspirantis praeportat pectoris iras,<br>huc huc adventate, meas audite querelas,<br>quas ego, vae miserae, extremis proferre medullis<br>cogor inops, ardens, amenti caeca furore.<br>quae quoniam verae nascuntur pectore ab imo,<br>vos nolite pati nostrum vanescere luctum,<br>sed quali solam Theseus me mente reliquit,<br>tali mente, deae, funestet seque suosque.’", "st": "64"}, {"sp": "N", "t": "has postquam maesto profudit pectore voces<br>supplicium saevis exposcens anxia factis,<br>adnuit invicto caelestum numine rector,<br>quo nutu tellus atque horrida contremuerunt<br>aequora concussitque micantia sidera mundus.<br>ipse autem caeca mentem caligine Theseus<br>consitus oblito dimisit pectore cuncta<br>quae mandata prius constanti mente tenebat,<br>dulcia nec maesto sustollens signa parenti<br>sospitem Erechtheum se ostendit visere portum<br>namque ferunt olim, classi cum moenia divae<br>linquentem gnatum ventis concrederet Aegeus,<br>talia complexum iuveni mandata dedisse:", "st": "64"}, {"sp": "N", "t": "‘gnate mihi longe iucundior unice vita,<br>gnate, ego quem in dubios cogor dimittere casus<br>reddite in extrema nuper mihi fine senectae,<br>quandoquidem fortuna mea ac tua fervida virtus<br>eripit invito mihi te, cui languida nondum<br>lumina sunt gnati cara saturata figura,<br>non ego te gaudens laetanti pectore mittam,<br>nec te ferre sinam fortunae signa secundae,<br>sed primum multas expromam mente querelas<br>canitiem terra atque infuso pulvere foedans,<br>inde infecta vago suspendam lintea malo,<br>nostros ut luctus nostraeque incendia mentis<br>carbasus obscurata decet ferrugine Hibera.<br>quod tibi si sancti concesserit incola Itoni,<br>quae nostrum genus ac sedes defendere Erechthei<br>adnuit, ut tauri respergas sanguine dextram,<br>tum vero facito ut memori tibi condita corde<br>haec vigeant mandata, nec ulla oblitteret aetas,<br>ut simul ac nostros invisent lumina collis,<br>funestam antennae deponant undique vestem<br>candidaque intorti sustollant vela rudentes,<br>quam primum cernens ut laeta gaudia mente<br>agnoscam, cum te reducem aetas prospera sistet.’", "st": "64"}, {"sp": "N", "t": "haec mandata prius constanti mente tenentem<br>Thesea ceu pulsae ventorum flamine nubes<br>aerium nivei montis liquere cacumen.<br>at pater, ut summa prospectum ex arce petebat<br>anxia in adsiduos absumens lumina fletus,<br>cum primum inflati conspexit lintea veli,<br>praecipitem sese scopulorum e vertice iecit<br>amissum credens immiti Thesea fato.<br>sic funesta domus ingressus tecta paterna<br>morte ferox Theseus, qualem Minoidi luctu<br>obtulerat mente immemori, talem ipse recepit.<br><br>quae tum prospectans cedentem maesta carinam<br>multiplices animo volvebat saucia curas.", "st": "64"}, {"sp": "N", "t": "at parte ex alia florens volitabat Iacchus<br>cum thiaso satyrorum et Nysigenis silenis<br>te quaerens, Ariadna, tuoque incensus amore.<br>…<br>quae tum alacres passim lymphata mente furebant<br>euhoe bacchantes, euhoe capita inflectentes.<br>harum pars tecta quatiebant cuspide thyrsos,<br>pars e divulso iactabant membra iuvenco,<br>pars sese tortis serpentibus incingebant,<br>pars obscura cavis celebrabant orgia cistis,<br>orgia quae frustra cupiunt audire profani,<br>plangebant aliae proceris tympana palmis<br>aut tereti tenuis tinnitus aere ciebant,<br>multis raucisonos efflabant cornua bombos<br>barbaraque horribili stridebat tibia cantu.<br>talibus amplifice vestis decorata figuris<br>pulvinar complexa suo velabat amictu.", "st": "64"}, {"sp": "N", "t": "quae postquam cupide spectando Thessala pubes<br>expleta est, sanctis coepit decedere divis.<br>hic, qualis flatu placidum mare matutino<br>horrificans Zephyrus proclivas incitat undas<br>aurora exoriente vagi sub limina solis,<br>quae tarde primum clementi flamine pulsae<br>procedunt, leviterque sonant plangore cachinni,<br>post vento crescente magis magis increbescunt<br>purpureaque procul nantes ab luce refulgent,<br>sic tum vestibuli linquentes regia tecta<br>ad se quisque vago passim pede discedebant.", "st": "64"}, {"sp": "N", "t": "quorum post abitum princeps e vertice Peli<br>advenit Chiron portans silvestria dona:<br>nam quoscumque ferunt campi, quos Thessala magnis<br>montibus ora creat, quos propter fluminis undas<br>aura parit flores tepidi fecunda Favoni,<br>hos indistinctis plexos tulit ipse corollis,<br>quo permulsa domus iucundo risit odore.<br>confestim Penios adest, viridantia Tempe,<br>Tempe quae silvae cingunt super impendentes,<br>naiasin linquens Doris celebranda choreis,<br>non vacuus: namque ille tulit radicitus altas<br>fagos ac recto proceras stipite laurus,<br>non sine nutanti platano lentaque sorore<br>flammati Phaethontis et aeria cupressu.<br>haec circum sedes late contexta locavit,<br>vestibulum ut molli velatum fronde vireret.<br>post hunc consequitur sollerti corde Prometheus<br>extenuata gerens veteris vestigia poenae<br>quam quondam silici restrictus membra catena<br>persolvit pendens e verticibus praeruptis.<br>inde pater divum sancta cum coniuge natisque<br>advenit, caelo te solum, Phoebe, relinquens<br>unigenamque simul cultricem montibus Idri:<br>Pelea nam tecum pariter soror adspernata est<br>nec Thetidis taedas voluit celebrare iugalis.", "st": "64"}, {"sp": "N", "t": "qui postquam niveis flexerunt sedibus artus,<br>large multiplici constructae sunt dape mensae,<br>cum interea infirmo quatientes corpora motu<br>veridicos Parcae coeperunt edere cantus.<br>his corpus tremulum complectens undique vestis<br>candida purpurea talos incinxerat ora,<br>at roseae niveo residebant vertice vittae,<br>aeternumque manus carpebant rite laborem.<br>laeva colum molli lana retinebat amictum,<br>dextera tum leviter deducens fila supinis<br>formabat digitis, tum prono in pollice torquens<br>libratum tereti versabat turbine fusum,<br>atque ita decerpens aequabat semper opus dens,<br>laneaque aridulis haerebant morsa labellis<br>quae prius in levi fuerant exstantia filo.<br>ante pedes autem candentis mollia lanae<br>vellera virgati custodibant calathisci.<br>haec tum clarisona vellentes vellera voce<br>talia divino fuderunt carmine fata,<br>carmine perfidiae quod post nulla arguet aetas:", "st": "64"}, {"sp": "N", "t": "‘o decus eximium magnis virtutibus augens,<br>Emathiae tutamen opis, clarissime nato,<br>accipe quod laeta tibi pandunt luce sorores,<br>veridicum oraclum. sed vos, quae fata secuntur,<br>currite ducentes subtegmina, currite, fusi.<br><br>adveniet tibi iam portans optata maritis<br>Hesperus, adveniet fausto cum sidere coniunx,<br>quae tibi flexanimo mentem perfundat amore<br>languidulosque paret tecum coniungere somnos<br>levia substernens robusto bracchia collo.<br>currite ducentes subtegmina, currite, fusi.<br><br>nulla domus tales unquam contexit amores,<br>nullus amor tali coniunxit foedere amantes<br>qualis adest Thetidi, qualis concordia Peleo.<br>currite ducentes subtegmina, currite, fusi.<br><br>nascetur vobis expers terroris Achilles,<br>hostibus haud tergo, sed forti pectore notus,<br>qui persaepe vago victor certamine cursus<br>flammea praevertet celeris vestigia cervae.<br>currite ducentes subtegmina, currite, fusi.<br><br>non illi quisquam bello se conferet heros,<br>cum Phrygii Teucro manabunt sanguine campi<br>Troicaque obsidens longinquo moenia bello<br>periuri Pelopis vastabit tertius heres.<br>currite ducentes subtegmina, currite, fusi.<br><br>illius egregias virtutes claraque facta<br>saepe fatebuntur gnatorum in funere matres,<br>cum incultum cano solvent a vertice crinem<br>putridaque infirmis variabunt pectora palmis.<br>currite ducentes subtegmina, currite, fusi.<br><br>namque velut densas praecerpens messor aristas<br>sole sub ardenti flaventia demetit arva,<br>Troiugenum infesto prosternet corpora ferro.<br>currite ducentes subtegmina, currite, fusi.<br><br>testis erit magnis virtutibus unda Scamandri,<br>quae passim rapido diffunditur Hellesponto,<br>cuius iter caesis angustans corporum acervis<br>alta tepefaciet permixta flumina caede.<br>currite ducentes subtegmina, currite, fusi.<br><br>denique testis erit morti quoque reddita praeda<br>cum teres excelso coacervatum aggere bustum<br>excipiet niveos percussae virginis artus.<br>Currite ducentes subtegmina, currite, fusi.<br><br>nam simul ac fessis dederit fors copiam Achivis<br>urbis Dardaniae Neptunia solvere vincla,<br>alta Polyxenia madefient caede sepulcra,<br>quae, velut ancipiti succumbens victima ferro,<br>proiciet truncum submisso poplite corpus.<br>currite ducentes subtegmina, currite, fusi.<br><br>quare agite optatos animi coniungite amores.<br>accipiat coniunx felici foedere divam,<br>dedatur cupido iam dudum nupta marito.<br>currite ducentes subtegmina, currite, fusi.<br><br>non illam nutrix orienti luce revisens<br>hesterno collum poterit circumdare filo<br>(currite ducentes subtegmina, currite, fusi),<br>anxia nec mater discordis maesta puellae<br>secubitu caros mittet sperare nepotes.<br>currite ducentes subtegmina, currite, fusi.’", "st": "64"}, {"sp": "N", "t": "talia praefantes quondam felicia Pelei<br>carmina divino cecinerunt pectore Parcae.<br>praesentes namque ante domos invisere castas<br>heroum et sese mortali ostendere coetu<br>caelicolae nondum spreta pietate solebant.<br>saepe pater divum templo in fulgente, revisens<br>annua cum festis venissent sacra diebus,<br>conspexit terra centum procumbere tauros.<br>saepe vagus Liber Parnasi vertice summo<br>Thyiadas effusis euantis crinibus egit,<br>cum Delphi tota certatim ex urbe ruentes<br>acciperent laeti divum fumantibus aris.<br>saepe in letifero belli certamine Mavors<br>aut rapidi Tritonis era aut Rhamnusia virgo<br>armatas hominum est praesens hortata catervas.<br>sed postquam tellus scelere est imbuta nefando,<br>iustitiamque omnes cupida de mente fugarunt,<br>perfudere manus fraterno sanguine fratres,<br>destitit exstinctos natus lugere parentes,<br>optavit genitor primaevi funera nati<br>Liber ut innuptae poteretur flore novercae,<br>ignaro mater substernens se impia nato<br>impia non verita est divos scelerare parentes,<br>omnia fanda nefanda malo permixta furore<br>iustificam nobis mentem avertere deorum.<br>quare nec talis dignantur visere coetus<br>nec se contingi patiuntur lumine claro.", "st": "64"}, {"sp": "N", "t": "Etsi me adsiduo defectum cura dolore<br>sevocat a doctis, Ortale, virginibus,<br>nec potis est dulcis Musarum expromere fetus<br>mens animi: tantis fluctuat ipsa malis,—<br>namque mei nuper Lethaeo gurgite fratris<br>pallidulum manans adluit unda pedem,<br>Troia Rhoeteo quem subter litore tellus<br>Ereptum nostris obterit ex oculis.<br>…<br>nunquam ego te vita frater amabilior<br>adspiciam posthac: at certe semper amabo,<br>semper maesta tua carmina morte canam,<br>qualia sub densis ramorum concinit umbris<br>Daulias absumpti fata gemens Ityli,—<br>sed tamen in tantis maeroribus, Ortale, mitto<br>haec expressa tibi carmina Battiadae,<br>ne tua dicta vagis nequiquam credita ventis<br>effluxisse meo forte putes animo,<br>ut missum sponsi furtivo munere malum<br>procurrit casto virginis e gremio,<br>quod miserae oblitae molli sub veste locatum,<br>dum adventu matris prosilit, excutitur;<br>atque illud prono praeceps agitur decursu,<br>huic manat tristi conscius ore rubor.", "st": "65"}, {"sp": "N", "t": "Omnia qui magni dispexit lumina mundi,<br>qui stellarum ortus comperit atque obitus,<br>flammeus ut rapidi solis nitor obscuretur,<br>ut cedant certis sidera temporibus,<br>ut Triviam furtim sub Latmia saxa relegans<br>dulcis amor gyro devocet aerio,<br>idem me ille Conon caelesti in lumine vidit<br>e Bereniceo vertice caesariem<br>fulgentem clare, quam cunctis illa deorum<br>levia protendens bracchia pollicita est,<br>qua rex tempestate novo auctus hymenaeo<br>vastatum finis iuerat Assyrios,<br>dulcia nocturnae portans vestigia rixae<br>quam de virgineis gesserat exuviis.", "st": "66"}, {"sp": "N", "t": "estne novis nuptis odio Venus, atque parentum<br>frustrantur falsis gaudia lacrimulis<br>ubertim thalami quas intra limina fundunt?<br>non, ita me divi vera gemunt, iuerint.<br>id mea me multis docuit regina querelis<br>invisente novo proelia torva viro.<br>at tu non orbum luxti deserta cubile,<br>sed fratris cari flebile discidium?<br>quam penitus maestas exedit cura medullas!<br>ut tibi tunc toto pectore sollicitae<br>sensibus ereptis mens excidit! at te ego certe<br>cognoram a parva virgine magnanimam.<br>anne bonum oblita es facinus, quo regium adepta es<br>coniugium, quod non fortior ausit alis?<br>sed tum maesta virum mittens quae verba locuta es!<br>Iuppiter, ut tristi lumina saepe manu!<br>quis te mutavit tantus deus? an quod amantes<br>non longe a caro corpore abesse volunt?<br>atque ibi me cunctis pro dulci coniuge divis<br>non sine taurino sanguine pollicita es,<br>si reditum tetulisset. is haud in tempore longo<br>captam Asiam Aegypti finibus addiderat.<br>quis ego pro factis caelesti reddita coetu<br>pristina vota novo munere dissolvo.", "st": "66"}, {"sp": "N", "t": "invita, o regina, tuo de vertice cessi,<br>invita: adiuro teque tuumque caput:<br>digna ferat quod si quis inaniter adiurarit:<br>sed qui se ferro postulet esse parem?<br>ille quoque eversus mons est quem maximum in oris<br>progenies Thiae clara supervehitur,<br>cum Medi peperere novum mare, cumque inventus<br>per medium classi barbara navit Athon.<br>quid facient crines, cum ferro talia cedant?<br>Iuppiter, ut Chalybon omne genus pereat,<br>et qui principio sub terra quaerere venas<br>institit ac ferri fingere duritiem!", "st": "66"}, {"sp": "N", "t": "abiunctae paulo ante comae mea fata sorores<br>lugebant, cum se Memnonis Aethiopis<br>unigena impellens nutantibus aera pennis<br>obtulit Arsinoes † elocridicos ales equus,<br>isque per aetherias me tollens avolat umbras<br>et Veneris casto conlocat in gremio.<br>ipsa suum Zephyritis eo famulum legarat,<br>Graia Canopiis incola litoribus,<br>†hi dii ven ibi vario ne solum in lumine caeli<br>ex Ariadneis aurea temporibus<br>fixa corona foret, sed nos quoque fulgeremus<br>devotae flavi verticis exuviae,<br>uvidulam a fletu cedentem ad templa deum me<br>sidus in antiquis diva novum posuit:<br>Virginis et saevi contingens namque Leonis<br>lumina, Callisto iuncta Lycaoniae,<br>vertor in occasum, tardum dux ante Booten,<br>qui vix sero alto mergitur Oceano.", "st": "66"}, {"sp": "N", "t": "sed quamquam me nocte premunt vestigia divum,<br>lux autem canae Tethyi restituit,<br>(pace tua fari hic liceat, Rhamnusia virgo:<br>namque ego non ullo vera timore tegam,<br>nec si me infestis discerpent sidera dictis,<br>condita quin veri pectoris evoluam)<br>non his tam laetor rebus quam me afore semper<br>afore me a dominae vertice discrucior,<br>quicum ego, dum virgo quondam fuit, omnibus expers<br>unguentis, una milia multa bibi.", "st": "66"}, {"sp": "N", "t": "nunc vos optato quom iunxit lumine taeda,<br>non prius unanimis corpora coniugibus<br>tradite nudantes reiecta veste papillas,<br>quam iucunda mihi munera libet onyx,<br>vester onyx, casto colitis quae iura cubili.<br>sed quae se impuro dedit adulterio,<br>illius ah mala dona levis bibat irrita pulvis:<br>namque ego ab indignis praemia nulla peto.<br>sed magis, o nuptae, semper concordia vestras,<br>semper amor sedes incolat adsiduus.<br>tu vero, regina, tuens cum sidera divam<br>placabis festis luminibus Venerem,<br>unguinis expertem non siris esse tuam me,<br>sed potius largis adfice muneribus.<br>sidera cur retinent? utinam coma regia fiam<br>proximus Hydrochoi fulgeret Oarion.", "st": "66"}, {"sp": "N", "t": "O dulci iucunda viro, iucunda parenti,<br>salve, teque bona Iuppiter auctet ope,<br>Ianua, quam Balbo dicunt servisse benigne<br>olim, cum sedes ipse senex tenuit,<br>quamque ferunt rursus voto servisse maligne,<br>postquam es porrecto facta marita sene,<br>dic agedum nobis quare mutata feraris<br>in dominum veterem deseruisse fidem.", "st": "67"}, {"sp": "N", "t": "‘non (ita Caecilio placeam, cui tradita nunc sum)<br>culpa mea est, quamquam dicitur esse mea,<br>nec peccatum a me quisquam pote dicere quicquam:<br>†verum istius populi ianua qui te facit!<br>qui, quacumque aliquid reperitur non bene factum,<br>ad me omnes clamant, “Ianua, culpa tua est.”’", "st": "67"}, {"sp": "N", "t": "non istuc satis est uno te dicere verbo,<br>sed facere ut quivis sentiat et videat.", "st": "67"}, {"sp": "N", "t": "‘qui possum? nemo quaerit nec scire laborat.’", "st": "67"}, {"sp": "N", "t": "nos volumus; nobis dicere ne dubita.", "st": "67"}, {"sp": "N", "t": "‘primum igitur, virgo quod fertur tradita nobis,<br>falsum est. non illam vir prior attigerit,<br>languidior tenera cui pendens sicula beta<br>nunquam se mediam sustulit ad tunicam:<br>sed pater illius gnati violasse cubile<br>dicitur et miseram conscelerasse domum,<br>sive quod impia mens caeco flagrabat amore,<br>seu quod iners sterili semine natus erat<br>et quaerendus is unde foret nervosius illud<br>quod posset zonam solvere virgineam.’", "st": "67"}, {"sp": "N", "t": "egregium narras mira pietate parentem,<br>qui ipse sui gnati minxerit in gremium.", "st": "67"}, {"sp": "N", "t": "‘atqui non solum hoc se dicit cognitum habere<br>Brixia † chinea suppositum specula,<br>flavus quam molli praecurrit flumine Mella,<br>Brixia, Veronae mater amata meae,<br>sed de Postumio et Corneli narrat amore,<br>cum quibus illa malum fecit adulterium.", "st": "67"}, {"sp": "N", "t": "dixerit hic aliquis, “quid? tu istaec, Ianua, nosti,<br>cui nunquam domini limine abesse licet,<br>nec populum auscultare, sed hic suffixa tigillo<br>tantum operire soles aut aperire domum?”", "st": "67"}, {"sp": "N", "t": "saepe illam audivi furtiva voce loquentem<br>solam cum ancillis haec sua flagitia,<br>nomine dicentem quos diximus, ut pote quae mi<br>speraret nec linguam esse nec auriculam.<br>praeterea addebat quendam, quem dicere nolo<br>nomine ne tollat rubra supercilia.<br>longus homo est, magnas cui lites intulit olim<br>falsum mendaci ventre puerperium.’", "st": "67"}, {"sp": "N", "t": "Quod mihi fortuna casuque oppressus acerbo<br>conscriptum hoc lacrimis mittis epistolium,<br>naufragum ut eiectum spumantibus aequoris undis<br>sublevem et a mortis limine restituam,<br>quem neque sancta Venus molli requiescere somno<br>desertum in lecto caelibe perpetitur,<br>nec veterum dulci scriptorum carmine musae<br>oblectant, cum mens anxia pervigilat,<br>id gratum est mihi, me quoniam tibi dicis amicum<br>muneraque et Musarum hinc petis et Veneris.<br>sed tibi ne mea sint ignota incommoda, Manli,<br>neu me odisse putes hospitis officium,<br>accipe quis merser fortunae fluctibus ipse,<br>ne amplius a misero dona beata petas.<br>tempore quo primum vestis mihi tradita pura est,<br>iucundum cum aetas florida ver ageret,<br>multa satis lusi; non est dea nescia nostri<br>quae dulcem curis miscet amaritiem:<br>sed totum hoc studium luctu fraterna mihi mors<br>abstulit. o misero frater adempte mihi,<br>tu mea tu moriens fregisti commoda, frater,<br>tecum una tota est nostra sepulta domus,<br>omnia tecum una perierunt gaudia nostra,<br>quae tuus in vita dulcis alebat amor.<br>cuius ego interitu tota de mente fugavi<br>haec studia atque omnes delicias animi.<br>quare, quod scribis Veronae turpe Catullo<br>esse quod hic quisquis de meliore nota<br>frigida deserto tepefactet membra cubili,<br>id, Manli, non est turpe, magis miserum est.<br>ignosces igitur, si, quae mihi luctus ademit,<br>haec tibi non tribuo munera, cum nequeo.<br>nam quod scriptorum non magna est copia apud me,<br>hoc fit quod Romae vivimus: illa domus,<br>illa mihi sedes, illic mea carpitur aetas;<br>huc una ex multis capsula me sequitur.<br>quod cum ita sit, nolim statuas nos mente maligna<br>id facere aut animo non satis ingenuo<br>quod tibi non utriusque petenti copia parta est:<br>ultro ego deferrem, copia si qua foret.", "st": "68a"}, {"sp": "N", "t": "non possum reticere, deae, qua me Allius in re<br>iuverit aut quantis iuverit officiis,<br>ne fugiens saeclis obliviscentibus aetas<br>illius hoc caeca nocte tegat studium:<br>sed dicam vobis, vos porro dicite multis<br>milibus et facite haec charta loquatur anus<br>…<br>notescatque magis mortuus atque magis,<br>nec tenuem texens sublimis aranea telam<br>in deserto Alli nomine opus faciat.", "st": "68b"}, {"sp": "N", "t": "nam mihi quam dederit duplex Amathusia curam<br>scitis, et in quo me corruerit genere,<br>cum tantum arderem quantum Trinacria rupes<br>lymphaque in Oetaeis Malia Thermopylis,<br>maesta neque adsiduo tabescere lumina fletu<br>cessarent tristique imbre madere genae,<br>qualis in aerii perlucens vertice montis<br>rivus muscoso prosilit e lapide,<br>qui, cum de prona praeceps est valle volutus,<br>per medium densi transit iter populi,<br>dulce viatori lasso in sudore levamen<br>cum gravis exustos aestus hiulcat agros.<br>hic, velut in nigro iactatis turbine nautis<br>lenius adspirans aura secunda venit<br>iam prece Pollucis, iam Castoris implorata,<br>tale fuit nobis Allius auxilium.", "st": "68b"}, {"sp": "N", "t": "is clausum lato patefecit limite campum,<br>isque domum nobis isque dedit dominae,<br>ad quam communes exerceremus amores.<br>quo mea se molli candida diva pede<br>intulit et trito fulgentem in limine plantam<br>innixa arguta constituit solea,<br>coniugis ut quondam flagrans advenit amore<br>Protesilaeam Laodamia domum<br>inceptam frustra, nondum cum sanguine sacro<br>hostia caelestis pacificasset eros.<br>nil mihi tam valde placeat, Rhamnusia virgo,<br>quod temere invitis suscipiatur eris.<br>quam ieiuna pium desideret ara cruorem<br>docta est amisso Laodamia viro,<br>coniugis ante coacta novi dimittere collum<br>quam veniens una atque altera rursus hiems<br>noctibus in longis avidum saturasset amorem,<br>posset ut abrupto vivere coniugio:<br>quod scibant Parcae non longo tempore abesse,<br>si miles muros isset ad Iliacos:<br>nam tum Helenae raptu primores Argivorum<br>coeperat ad sese Troia ciere viros,<br>Troia (nefas) commune sepulcrum Asiae Europaeque,<br>Troia virum et virtutum omnium acerba cinis:<br>quaene etiam nostro letum miserabile fratri<br>attulit. Hei misero frater adempte mihi,<br>hei misero fratri iucundum lumen ademptum,<br>tecum una tota est nostra sepulta domus,<br>omnia tecum una perierunt gaudia nostra,<br>quae tuus in vita dulcis alebat amor.<br>quem nunc tam longe non inter nota sepulcra<br>nec prope cognatos compositum cineres,<br>sed Troia obscena, Troia infelice sepultum<br>detinet extremo terra aliena solo.<br>ad quam tum properans fertur simul undique pubes<br>Graeca penetralis deseruisse focos,<br>ne Paris abducta gavisus libera moecha<br>otia pacato degeret in thalamo.", "st": "68b"}, {"sp": "N", "t": "quo tibi tum casu, pulcherrima Laodamia,<br>ereptum est vita dulcius atque anima<br>coniugium: tanto te absorbens vertice amoris<br>aestus in abruptum detulerat barathrum,<br>quale ferunt Grai Pheneum prope Cylleneum<br>siccare emulsa pingue palude solum,<br>quod quondam caesis montis fodisse medullis<br>audit falsiparens Amphitryoniades,<br>tempore quo certa Stymphalia monstra sagitta<br>perculit imperio deterioris eri,<br>pluribus ut caeli tereretur ianua divis,<br>Hebe nec longa virginitate foret.<br>sed tuus altus amor barathro fuit altior illo,<br>qui tunc indomitam ferre iugum docuit.<br>nam nec tam carum confecto aetate parenti<br>una caput seri nata nepotis alit,<br>qui, cum divitiis vix tandem inventus avitis<br>nomen testatas intulit in tabulas,<br>impia derisi gentilis gaudia tollens<br>suscitat a cano vulturium capiti:<br>nec tantum niveo gavisa est ulla columbo<br>compar, quae multo dicitur improbius<br>oscula mordenti semper decerpere rostro<br>quam quae praecipue multivola est mulier:<br>sed tu horum magnos vicisti sola furores,<br>ut semel es flavo conciliata viro.", "st": "68b"}, {"sp": "N", "t": "aut nihil aut paulo cui tum concedere digna<br>lux mea se nostrum contulit in gremium,<br>quam circumcursans hinc illinc saepe Cupido<br>fulgebat crocina candidus in tunica.<br>quae tamenetsi uno non est contenta Catullo,<br>rara verecundae furta feremus erae,<br>ne nimium simus stultorum more molesti:<br>saepe etiam Iuno, maxima caelicolum,<br>coniugis in culpa flagrantem concoquit iram<br>noscens omnivoli plurima furta Iovis.<br>atqui nec divis homines componier aequum est<br>…<br>…<br>ingratum tremuli tolle parentis onus.<br>nec tamen illa mihi dextra deducta paterna<br>fragrantem Assyrio venit odore domum,<br>sed furtiva dedit mira munuscula nocte<br>ipsius ex ipso dempta viri gremio.<br>quare illud satis est, si nobis is datur unis<br>quem lapide illa diem candidiore notat.", "st": "68b"}, {"sp": "N", "t": "hoc tibi quod potui confectum carmine munus<br>pro multis, Alli, redditur officiis,<br>ne vestrum scabra tangat robigine nomen<br>haec atque illa dies atque alia atque alia.<br>huc addent divi quam plurima, quae Themis olim<br>antiquis solita est munera ferre piis:<br>sitis felices et tu simul et tua vita<br>et domus, in qua nos lusimus et domina,<br>et qui principio nobis † terram dedit aufert,<br>a quo sunt primo omnia nata bona,<br>et longe ante omnes mihi quae me carior ipso est,<br>lux mea, qua viva vivere dulce mihi est.", "st": "68b"}, {"sp": "N", "t": "Noli admirari quare tibi femina nulla,<br>Rufe, velit tenerum supposuisse femur,<br>non si illam rarae labefactes munere vestis<br>aut perluciduli deliciis lapidis.<br>laedit te quaedam mala fabula, qua tibi fertur<br>valle sub alarum trux habitare caper.<br>hunc metuunt omnes. neque mirum: nam mala valde est<br>bestia, nec quicum bella puella cubet.<br>quare aut crudelem nasorum interfice pestem,<br>aut admirari desine cur fugiunt.", "st": "69"}, {"sp": "N", "t": "Nulli se dicit mulier mea nubere malle<br>quam mihi, non si se Iuppiter ipse petat.<br>dicit: sed mulier cupido quod dicit amanti<br>in vento et rapida scribere oportet aqua.", "st": "70"}, {"sp": "N", "t": "Si cui iure bono sacer alarum obstitit hircus,<br>aut si quem merito tarda podagra secat,<br>Aemulus iste tuus, qui vestrum exercet amorem,<br>mirifice est a te nactus utrumque malum.<br>nam quotiens futuit totiens ulciscitur ambos:<br>illam adfligit odore, ipse perit podagra.", "st": "71"}, {"sp": "N", "t": "Dicebas quondam solum te nosse Catullum,<br>Lesbia, nec prae me velle tenere Iovem.<br>dilexi tum te non tantum ut vulgus amicam,<br>sed pater ut gnatos diligit et generos.<br>nunc te cognovi: quare etsi impensius uror,<br>multo mi tamen es vilior et levior.<br>qui potis est? inquis. quod amantem iniuria talis<br>cogit amare magis, sed bene velle minus.", "st": "72"}, {"sp": "N", "t": "Desine de quoquam quicquam bene velle mereri<br>aut aliquem fieri posse putare pium.<br>omnia sunt ingrata, nihil fecisse benigne:<br>immo etiam taedet, taedet obestque magis:<br>ut mihi, quem nemo gravius nec acerbius urget<br>Quam modo qui me unum atque unicum amicum habuit.", "st": "73"}, {"sp": "N", "t": "Gellius audierat patruum obiurgare solere,<br>si quis delicias diceret aut faceret.<br>hoc ne ipsi accideret, patrui perdepsuit ipsam<br>uxorem et patruum reddidit Harpocratem.<br>quod voluit fecit: nam, quamvis irrumet ipsum<br>nunc patruum, verbum non faciet patruus.", "st": "74"}, {"sp": "N", "t": "Huc est mens deducta tua, mea Lesbia, culpa,<br>atque ita se officio perdidit ipsa suo,<br>ut iam nec bene velle queat tibi, si optuma fias,<br>nec desistere amare, omnia si facias.", "st": "75"}, {"sp": "N", "t": "Si qua recordanti benefacta priora voluptas<br>est homini, cum se cogitat esse pium,<br>nec sanctam violasse fidem, nec foedere in ullo<br>divum ad fallendos numine abusum homines,<br>multa parata manent in longa aetate, Catulle,<br>ex hoc ingrato gaudia amore tibi.<br>nam quaecumque homines bene cuiquam aut dicere possunt<br>aut facere, haec a te dictaque factaque sunt:<br>omnia quae ingratae perierunt credita menti.<br>quare cur tu te iam amplius excrucies?<br>quin tu animo offirmas atque istinc teque reducis<br>et dis invitis desinis esse miser?<br>difficile est longum subito deponere amorem;<br>difficile est, verum hoc qua libet efficias.<br>una salus haec est, hoc est tibi pervincendum;<br>hoc facias, sive id non pote sive pote.<br>o di, si vestrum est misereri, aut si quibus unquam<br>extremam iam ipsa in morte tulistis opem,<br>me miserum adspicite et, si vitam puriter egi,<br>eripite hanc pestem perniciemque mihi!<br>hei mihi subrepens imos ut torpor in artus<br>expulit ex omni pectore laetitias.<br>non iam illud quaero, contra ut me diligat illa,<br>aut, quod non potis est, esse pudica velit:<br>ipse valere opto et taetrum hunc deponere morbum.<br>o di, reddite mi hoc pro pietate mea.", "st": "76"}, {"sp": "N", "t": "Rufe mihi frustra ac nequiquam credite amice<br>(frustra? immo magno cum pretio atque malo),<br>sicine subrepsti mi atque intestina perurens<br>hei misero eripuisti omnia nostra bona?<br>eripuisti, eheu nostrae crudele venenum<br>vitae, eheu nostrae pestis amicitiae.", "st": "77"}, {"sp": "N", "t": "Gallus habet fratres, quorum est lepidissima coniunx<br>alterius, lepidus filius alterius.<br>Gallus homo est bellus: nam dulces iungit amores,<br>cum puero ut bello bella puella cubet.<br>Gallus homo est stultus nec se videt esse maritum,<br>qui patruus patrui monstret adulterium.<br>…<br>…<br>Sed nunc id doleo quod purae pura puellae<br>savia comminxit spurca saliva tua.<br>verum id non impune feres: nam te omnia saecla<br>noscent et qui sis fama loquetur anus.", "st": "78"}, {"sp": "N", "t": "Lesbius est pulcher: quid ni? quem Lesbia malit<br>quam te cum tota gente, Catulle, tua.<br>sed tamen hic pulcher vendat cum gente Catullum,<br>si tria notorum savia reppererit.", "st": "79"}, {"sp": "N", "t": "Quid dicam, Gelli, quare rosea ista labella<br>Hiberna fiant candidiora nive,<br>mane domo cum exis et cum te octava quiete<br>e molli longo suscitat hora die?<br>nescio quid certe est: an vere fama susurrat<br>grandia te medii tenta vorare viri?<br>sic certe est: clamant Victoris rupta miselli<br>ilia, et emulso labra notata sero.", "st": "80"}, {"sp": "N", "t": "Nemone in tanto potuit populo esse, Iuventi,<br>bellus homo quem tu diligere inciperes<br>praeterquam iste tuus moribunda ab sede Pisauri<br>hospes inaurata pallidior statua?<br>qui tibi nunc cordi est, quem tu praeponere nobis<br>audes et nescis quod facinus facias.", "st": "81"}, {"sp": "N", "t": "Quinti, si tibi vis oculos debere Catullum<br>aut aliud si quid carius est oculis,<br>eripere ei noli multo quod carius illi<br>est oculis seu quid carius est oculis.", "st": "82"}, {"sp": "N", "t": "Lesbia mi praesente viro mala plurima dicit:<br>haec illi fatuo maxima laetitia est.<br>mule, nihil sentis. si nostri oblita taceret,<br>sana esset: nunc quod gannit et obloquitur,<br>non solum meminit, sed, quae multo acrior est res,<br>irata est: hoc est, uritur et loquitur.", "st": "83"}, {"sp": "N", "t": "Chommoda dicebat, si quando commode vellet<br>dicere, et insidias Arrius hinsidias,<br>et tum mirifice sperabat se esse locutum<br>cum quantum poterat dixerat hinsidias.<br>credo, sic mater, sic liber avunculus eius,<br>sic maternus avus dixerat atque avia<br>hoc misso in Syriam requierant omnibus aures:<br>audibant eadem haec leniter et leviter,<br>nec sibi postilla metuebant talia verba,<br>cum subito adfertur nuntius horribilis<br>Ionios fluctus, postquam illuc Arrius isset,<br>iam non Ionios esse, sed Hionios.", "st": "84"}, {"sp": "N", "t": "Odi et amo. quare id faciam fortasse requiris<br>nescio, sed fieri sentio et excrucior.", "st": "85"}, {"sp": "N", "t": "Quintia formosa est multis, mihi candida, longa,<br>recta est. haec ego sic singula confiteor,<br>totum illud ‘formosa’ nego: nam nulla venustas,<br>nulla in tam magno est corpore mica salis.<br>Lesbia formosa est, quae cum pulcherrima tota est,<br>tum omnibus una omnis subripuit Veneres.", "st": "86"}, {"sp": "N", "t": "Nulla potest mulier tantum se dicere amatam<br>vere, quantum a me Lesbia amata mea es<br>nulla fides ullo fuit unquam in foedere tanta<br>quanta in amore tuo ex parte reperta mea est.", "st": "87"}, {"sp": "N", "t": "Quid facit is, Gelli, qui cum matre atque sorore<br>prurit et abiectis pervigilat tunicis?<br>quid facit is patruum qui non sinit esse maritum?<br>ecquid scis quantum suscipiat sceleris?<br>suscipit, o Gelli, quantum non ultima Tethys<br>nec genitor nympharum abluit Oceanus:<br>nam nihil est quicquam sceleris quo prodeat ultra,<br>non si demisso se ipse voret capite.", "st": "88"}, {"sp": "N", "t": "Gellius est tenuis: quid ni? cui tam bona mater<br>tamque valens vivat tamque venusta soror<br>tamque bonus patruus tamque omnia plena puellis<br>cognatis, quare is desinat esse macer?<br>qui ut nihil attingat, nisi quod fas tangere non est,<br>quantumvis quare sit macer invenies.", "st": "89"}, {"sp": "N", "t": "Nascatur magus ex Gelli matrisque nefando<br>coniugio et discat Persicum haruspicium:<br>nam magus ex matre et gnato gignatur oportet,<br>si vera est Persarum impia religio,<br>gratus ut accepto veneretur carmine divos<br>omentum in flamma pingue liquefaciens.", "st": "90"}, {"sp": "N", "t": "Non ideo, Gelli, sperabam te mihi fidum<br>in misero hoc nostro, hoc perdito amore fore<br>quod te cognossem bene constantemve putarem<br>aut posse a turpi mentem inhibere probro,<br>sed neque quod matrem nec germanam esse videbam<br>hanc tibi cuius me magnus edebat amor;<br>et quamvis tecum multo coniungerer usu,<br>non satis id causae credideram esse tibi.<br>tu satis id duxti: tantum tibi gaudium in omni<br>culpa est in quacumque est aliquid sceleris.", "st": "91"}, {"sp": "N", "t": "Lesbia mi dicit semper male nec tacet unquam<br>de me: Lesbia me dispeream nisi amat.<br>quo signo? quia sunt totidem mea: deprecor illam<br>adsidue, verum dispeream nisi amo.", "st": "92"}, {"sp": "N", "t": "Nil nimium studeo, Caesar, tibi velle placere,<br>nec scire utrum sis albus an ater homo.", "st": "93"}, {"sp": "N", "t": "Mentula moechatur. moechatur mentula certe.<br>hoc est quod dicunt, ipsa olera olla legit.", "st": "94"}, {"sp": "N", "t": "Zmyrna mei Cinnae nonam post denique messem<br>quam coepta est nonamque edita post hiemem,<br>milia cum interea quingenta Hortensius uno<br>…<br>Zmyrna cavas Satrachi penitus mittetur ad undas,<br>Zmyrnam cana diu saecula pervolvent.<br>at Volusi annales Paduam morientur ad ipsam<br>et laxas scombris saepe dabunt tunicas.<br>parva mei mihi sint cordi monumenta sodalis:<br>at populus tumido gaudeat Antimacho.", "st": "95"}, {"sp": "N", "t": "Si quicquam mutis gratum acceptumve sepulcris<br>accidere a nostro, Calve, dolore potest,<br>quo desiderio veteres renovamus amores<br>atque olim missas flemus amicitias,<br>certe non tanto mors immatura dolori est<br>Quintiliae, quantum gaudet amore tuo.", "st": "96"}, {"sp": "N", "t": "Non (ita me di ament) quicquam referre putavi<br>utrumne os an culum olfacerem Aemilio.<br>nilo mundius hoc, nihiloque immundius illud,<br>verum etiam culus mundior et melior:<br>nam sine dentibus est. hoc dentis sesquipedalis,<br>gingivas vero ploxeni habet veteris,<br>praeterea rictum qualem diffissus in aestu<br>meientis mulae cunnus habere solet.<br>hic futuit multas et se facit esse venustum,<br>et non pistrino traditur atque asino?<br>quem si qua attingit, non illam posse putemus<br>aegroti culum lingere carnificis?", "st": "97"}, {"sp": "N", "t": "In te, si in quemquam, dici pose, putide Victi,<br>id quod verbosis dicitur et fatuis:<br>ista cum lingua, si usus veniat tibi, possis<br>culos et crepidas lingere carpatinas.<br>si nos omnino vis omnes perdere, Victi,<br>hiscas: omnino quod cupis efficies.", "st": "98"}, {"sp": "N", "t": "Subripui tibi, dum ludis, mellite Iuventi,<br>saviolum dulci dulcius ambrosia.<br>verum id non impune tuli: namque amplius horam<br>suffixum in summa me memini esse cruce,<br>dum tibi me purgo nec possum fletibus ullis<br>tantillum vestrae demere saevitiae.<br>nam simul id factum est, multis diluta labella<br>guttis abstersisti omnibus articulis,<br>ne quicquam nostro contractum ex ore maneret,<br>tanquam commictae spurca saliva lupae.<br>praeterea infesto miserum me tradere Amori<br>non cessasti omnique excruciare modo,<br>ut mi ex ambrosia mutatum iam fores illud<br>saviolum tristi tristius elleboro.<br>quam quoniam poenam misero proponis amori,<br>nunquam iam posthac basia subripiam.", "st": "99"}, {"sp": "N", "t": "Caelius Aufilenum et Quintius Aufilenam<br>flos Veronensum depereunt iuvenum,<br>hic fratrem, ille sororem. hoc est quod dicitur illud<br>fraternum vere dulce sodalicium.<br>cui faveam potius? Caeli, tibi: nam tua nobis<br>per facta exhibita est unica amicitia<br>cum vesana meas torreret flamma medullas.<br>sis felix, Caeli, sis in amore potens.", "st": "100"}, {"sp": "N", "t": "Multas per gentes et multa per aequora vectus<br>advenio has miseras, frater, ad inferias,<br>ut te postremo donarem munere mortis<br>et mutam nequiquam adloquerer cinerem,<br>quandoquidem fortuna mihi tete abstulit ipsum,<br>heu miser indigne frater adempte mihi.<br>nunc tamen interea haec, prisco quae more parentum<br>tradita sunt tristi munere ad inferias,<br>accipe fraterno multum manantia fletu<br>atque in perpetuum, frater, ave atque vale.", "st": "101"}, {"sp": "N", "t": "Si quicquam tacito commissum est fido ab amico<br>cuius sit penitus nota fides animi,<br>meque esse invenies illorum iure sacratum,<br>Corneli, et factum me esse puta Harpocratem.", "st": "102"}, {"sp": "N", "t": "Aut sodes mihi redde decem sestertia, Silo,<br>deinde esto quamvis saevus et indomitus:<br>aut, si te nummi delectant, desine quaeso<br>Leno esse atque idem saevus et indomitus.", "st": "103"}, {"sp": "N", "t": "Credis me potuisse meae maledicere vitae,<br>ambobus mihi quae carior est oculis?<br>non potui, nec, si possem, tam perdite amarem:<br>sed tu cum Tappone omnia monstra facis.", "st": "104"}, {"sp": "N", "t": "Mentula conatur Pipleum scandere montem:<br>Musae furcillis praecipitem eiciunt.", "st": "105"}, {"sp": "N", "t": "Cum puero bello praeconem qui videt esse,<br>quid credat, nisi se vendere discupere?", "st": "106"}, {"sp": "N", "t": "Si cui quid cupido optantique obtigit unquam<br>insperanti, hoc est gratum animo proprie.<br>quare hoc est gratum nobis quoque, carius auro,<br>quod te restituis, Lesbia, mi cupido:<br>restituis cupido atque insperanti, ipsa refers te<br>nobis. o lucem candidiore nota!<br>quis me uno vivit felicior, aut magis hac res<br>optandas vita dicere quis poterit?", "st": "107"}, {"sp": "N", "t": "Si, Comini, populi arbitrio tua cana senectus<br>spurcata impuris moribus intereat,<br>non equidem dubito quin primum inimica bonorum<br>lingua exsecta avido sit data vulturio,<br>effossos oculos voret atro gutture corvus,<br>intestina canes, cetera membra lupi.", "st": "108"}, {"sp": "N", "t": "Iucundum, mea vita, mihi proponis amorem<br>hunc nostrum inter nos perpetuumque fore.<br>di magni, facite ut vere promittere possit<br>atque id sincere dicat et ex animo,<br>ut liceat nobis tota perducere vita<br>aeternum hoc sanctae foedus amicitiae.", "st": "109"}, {"sp": "N", "t": "Aufilena, bonae semper laudantur amicae:<br>accipiunt pretium quod facere instituunt.<br>tu, quod promisti mihi, quod mentita, inimica es;<br>quod nec das et fers saepe, facts facinus.<br>aut facere ingenuae est, aut non promisse pudicae,<br>Aufilena, fuit: sed data corripere<br>fraudando † efficit plus quam meretricis avarae,<br>quae sese toto corpore prostituit.", "st": "110"}, {"sp": "N", "t": "Aufilena, viro contentam vivere solo<br>nuptarum laus e laudibus eximiis:<br>sed cuivis quamvis potius succumbere par est<br>quam matrem fratres ex patruo parere.", "st": "111"}, {"sp": "N", "t": "Multus homo est, Naso, neque tecum multus homo est qui<br>descendit: Naso, multus es et pathicus.", "st": "112"}, {"sp": "N", "t": "Consule Pompeio primum duo, Cinna, solebant<br>Maeciliam: facto consule nunc iterum<br>manserunt duo, sed creverunt milia in unum<br>singula. fecundum semen adulterio.", "st": "113"}, {"sp": "N", "t": "Firmanus saltu non falso Mentula dives<br>fertur, qui tot res in se habet egregias,<br>aucupium omne genus, piscis, prata, arva, ferasque.<br>nequiquam: fructus sumptibus exsuperat.<br>quare concedo sit dives, dum omnia desint;<br>saltum laudemus, dum domo ipse egeat.", "st": "114"}, {"sp": "N", "t": "Mentula habet iuxta triginta iugera prati,<br>quadraginta arvi: cetera sunt maria.<br>cur non divitiis Croesum superare potis sit<br>uno qui in saltu tot bona possideat,<br>prata, arva, ingentis silvas saltusque paludesque<br>usque ad Hyperboreos et mare ad Oceanum?<br>omnia magna haec sunt, tamen ipse est maximus ultro,<br>non homo, sed vero mentula magna minax.", "st": "115"}, {"sp": "N", "t": "Saepe tibi studioso animo venante requirens<br>carmina uti possem mittere Battiadae<br>qui te lenirem nobis, neu conarere<br>tela infesta mihi mittere in usque caput,<br>hunc video mihi nunc frustra sumptum esse laborem,<br>Gelli, nec nostras hic valuisse preces.<br>contra nos tela ista tua evitamus amictu:<br>at fixus nostris tu dabis supplicium.", "st": "116"}], []);})();
